// Package topology models the declared system topology an integration
// system's host emits. The record declares the system's shape: its components
// (blocks) and the wiring between them, expressed inline on each component —
// the topics it subscribes to and publishes on, the API contracts it provides
// and consumes, and the external ports it uses. Top-level topics[] and
// ports[] sections carry the shared metadata (contracts, external systems)
// those inline references point at.
//
// The record carries only minted facts: the Dapr binding a port deploys as
// (its spec.type, address, credentials) is environment-owned deployment
// configuration in the GitOps repo, and an extractor's cadence is its CronJob
// there. Neither appears here.
//
// The CLI never derives a topology itself: the system host's `graph` verb
// prints the record — JSON only, on stdout — and consumers decode that stream.
package topology

import (
	"encoding/json"
	"fmt"
	"io"
)

const (
	// APIVersion is the topology schema this CLI understands. A record with
	// any other apiVersion is an error, not a guess.
	APIVersion = "topology.intropy.io/v1"

	// Kind is the expected document kind under APIVersion.
	Kind = "SystemTopology"
)

// Topology is one system's declared graph. Wiring is inlined on each component
// rather than kept in a separate edge list: a component names the topics it
// subscribes to and publishes on and the ports it uses. The top-level Topics
// and Ports sections are lookup tables the inline references resolve against
// (contract, external system).
type Topology struct {
	APIVersion string      `json:"apiVersion"`
	Kind       string      `json:"kind,omitempty"`
	System     string      `json:"system"`
	Components []Component `json:"components,omitempty"`
	Topics     []Topic     `json:"topics,omitempty"`
	Ports      []Port      `json:"ports,omitempty"`
	Contracts  []Contract  `json:"contracts,omitempty"`
	// APIs, each component's Provides/Consumes below, and MessageGroups
	// are sections whose element shape is not yet finalized, so they are
	// parsed opaquely: preserved for round-tripping to the frontend
	// without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
	// MessageGroups is the system's internal messagegroup section, emitted
	// by hosts new enough to model messages by name. A nil section on an
	// older host decodes identically to today.
	MessageGroups []json.RawMessage `json:"messagegroups,omitempty"`
	// Development is the host's local-run picture, present only when the
	// graph verb ran with --development against a host whose Intropy.Topology
	// is new enough to emit it. A nil Development means "no dev configuration
	// known" — older hosts, hosts without a development definition, and plain
	// graph runs all decode identically.
	Development *Development `json:"development,omitempty"`
}

// Development is the development section of a topology record: the host
// author's local substitutions, emitted by `graph --development`.
type Development struct {
	// Files maps an external port to the local folder that stands in for it
	// on a developer machine (the localstorage binding's root).
	Files []FilePort `json:"files,omitempty"`
}

// FilePort is one port's development file resolution. RootPath is declared
// relative to the system host's directory ("./test/erp-source"); the host
// library rejects paths that escape it, and consumers confine again before
// writing.
type FilePort struct {
	Port     string `json:"port"`
	RootPath string `json:"rootPath"`
}

// Component is a deployable block of the system. Kind is the block type
// (extractor, loader, transactional-integration, …). A component's directory,
// which joins it to its .intropy/scaffold.json project, is its Name relative
// to the system root.
type Component struct {
	Name       string        `json:"name"`
	Kind       string        `json:"kind"`
	Subscribes []TopicRef    `json:"subscribes,omitempty"`
	Publishes  []Publication `json:"publishes,omitempty"`
	Ports      []PortUse     `json:"ports,omitempty"`
	// Provides/Consumes are contract surfaces, parsed opaquely (see APIs).
	Provides []json.RawMessage `json:"provides,omitempty"`
	Consumes []json.RawMessage `json:"consumes,omitempty"`
}

// TopicRef is a component's subscription to a pub/sub topic.
type TopicRef struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// Publication is a component's output onto a pub/sub topic.
type Publication struct {
	PubSub string `json:"pubsub"`
	Topic  string `json:"topic"`
}

// PortUse is a component's use of an external port. Direction is "in"
// (external → component) or "out" (component → external).
type PortUse struct {
	Port      string `json:"port"`
	Direction string `json:"direction"`
}

// Topic is a declared pub/sub topic: the metadata for a (PubSub, Topic) pair
// components reference. Contract is the message contract it carries;
// Publishers/Subscribers name the components on each end.
type Topic struct {
	PubSub      string   `json:"pubsub"`
	Topic       string   `json:"topic"`
	Contract    string   `json:"contract,omitempty"`
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Contract is a message contract in the system's registry, keyed by Name —
// the same fully-qualified type name Topic.Contract references. ShortName is
// the bare type name (the join key to a scaffold record's values.contract).
// Schema is the contract's JSON Schema as the host emitted it; the CLI passes
// it through to the frontend without interpreting it. Fingerprint identifies
// the schema shape (a hash over its canonical form), so equal fingerprints
// mean equal shapes across systems.
type Contract struct {
	Name        string          `json:"name"`
	Kind        string          `json:"kind,omitempty"`
	ShortName   string          `json:"shortName,omitempty"`
	MediaType   string          `json:"mediaType,omitempty"`
	Fingerprint string          `json:"fingerprint,omitempty"`
	Schema      json.RawMessage `json:"schema,omitempty"`
}

// Port is an external system integration point. The name is its whole
// identity — the deployed Dapr binding type, address, and credentials are
// environment-owned deployment configuration, never part of the record.
// ExternalSystem is the system it fronts, Directions the directions it is
// wired in, and UsedBy the components that use it.
type Port struct {
	Name           string   `json:"name"`
	ExternalSystem string   `json:"externalSystem,omitempty"`
	Directions     []string `json:"directions,omitempty"`
	UsedBy         []string `json:"usedBy,omitempty"`
}

// Entry is one system's topology plus the workspace directory it belongs to,
// flattened into one self-describing JSON document for the API.
type Entry struct {
	Path string `json:"path"`
	Topology
}

// Decode parses a topology record from r (typically a host `graph` verb's
// stdout). A record whose apiVersion this CLI does not understand is an
// error, not a guess. Callers wrap the error with the record's origin.
func Decode(r io.Reader) (*Topology, error) {
	var t Topology
	if err := json.NewDecoder(r).Decode(&t); err != nil {
		return nil, fmt.Errorf("parse topology record: %w", err)
	}
	if t.APIVersion != APIVersion {
		return nil, fmt.Errorf("unsupported topology apiVersion %q (this CLI understands %q)",
			t.APIVersion, APIVersion)
	}
	return &t, nil
}

package dashboard

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/system"
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// syncSystemRequest is the optional POST /api/systems/{path} body.
type syncSystemRequest struct {
	// Force lets an update overwrite diverged declaration files (sys
	// update --force) or a create render into a non-empty host directory.
	Force bool `json:"force,omitempty"`
}

// syncSystemResponse reports what a host sync did. Action says which verb
// ran: "update" folded orphans into an existing host, "create" assembled a
// new one, "none" found an up-to-date host and wrote nothing.
type syncSystemResponse struct {
	Action      string   `json:"action"`
	HostDir     string   `json:"hostDir,omitempty"`
	System      string   `json:"system,omitempty"`
	Added       []string `json:"added,omitempty"`
	Kept        []string `json:"kept,omitempty"`
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// syncSystem is POST /api/systems/{path...}: re-assemble one system's host
// the way the CLI would — `sys update` when the directory already has a
// host, `sys create` when it does not. The path is the system directory,
// never the workspace root of a multi-system workspace: sys update's
// single-host contract holds per system.
func (s *apiServer) syncSystem(w http.ResponseWriter, r *http.Request) {
	dir, err := s.resolveSystemDir(r.PathValue("path"))
	if err != nil {
		writeError(w, http.StatusUnprocessableEntity, err.Error())
		return
	}

	var req syncSystemRequest
	dec := json.NewDecoder(io.LimitReader(r.Body, maxCreateBodyBytes))
	if err := dec.Decode(&req); err != nil && !errors.Is(err, io.EOF) {
		writeError(w, http.StatusBadRequest, "invalid request body: "+err.Error())
		return
	}

	// The same serialization bargain template creates make: two concurrent
	// syncs of one host would race on its files, and each run may clone the
	// template library.
	s.createMu.Lock()
	defer s.createMu.Unlock()

	// The host renders from the release the dashboard holds, so assembling a
	// system and scaffolding into it can never pin different ones.
	tag, err := s.libraryTag(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}

	hosts, _ := template.ListSystemHosts(dir)
	if len(hosts) == 0 {
		s.createHost(w, r, dir, tag, req.Force)
		return
	}
	s.updateHost(w, r, dir, tag, req.Force)
}

// updateHost runs `sys update` against the system directory: fold every
// scaffolded-but-undeclared component into the existing host. No orphans is
// a successful no-op (action "none"), matching the command's own contract.
func (s *apiServer) updateHost(w http.ResponseWriter, r *http.Request, dir, tag string, force bool) {
	var out, logs bytes.Buffer
	err := system.Update(r.Context(), system.UpdateOptions{
		StartDir:   dir,
		Force:      force,
		Version:    tag,
		OutputJSON: "-",
		Stdout:     &out,
		Stderr:     &logs,
		UserAgent:  s.templates.userAgent,
		Owner:      s.templates.owner,
		Repo:       s.templates.repo,
		Source:     s.templates.source,
	})
	if err != nil {
		writeError(w, syncErrorStatus(err), err.Error())
		return
	}

	resp := syncSystemResponse{Action: "none", Diagnostics: diagnosticLines(logs.String())}
	// The result document is only written when the update added something;
	// an empty stdout is the no-orphans path.
	var res system.UpdateResult
	if out.Len() > 0 && json.Unmarshal(out.Bytes(), &res) == nil {
		resp.Action = "update"
		resp.HostDir = s.relPath(res.HostDir)
		resp.System = res.System
		resp.Added = res.Added
		resp.Kept = res.Kept
	}
	writeJSON(w, http.StatusOK, resp)
}

// createHost runs `sys create` for a system directory that has no host yet:
// the system is named after its directory (the same rule that labels the
// workspace pseudo-system) and the host renders inside it as <name>-host,
// a sibling of the components and the contracts project.
func (s *apiServer) createHost(w http.ResponseWriter, r *http.Request, dir, tag string, force bool) {
	name := hostSystemName(dir)
	var out, logs bytes.Buffer
	err := system.Create(r.Context(), system.CreateOptions{
		Name:       name,
		StartDir:   dir,
		OutputDir:  filepath.Join(dir, xstrings.ToKebabCase(name)+"-host"),
		Version:    tag,
		Force:      force,
		OutputJSON: "-",
		Stdout:     &out,
		Stderr:     &logs,
		UserAgent:  s.templates.userAgent,
		Owner:      s.templates.owner,
		Repo:       s.templates.repo,
		Source:     s.templates.source,
	})
	if err != nil {
		writeError(w, syncErrorStatus(err), err.Error())
		return
	}

	resp := syncSystemResponse{Action: "create", Diagnostics: diagnosticLines(logs.String())}
	var res system.CreateResult
	if out.Len() > 0 && json.Unmarshal(out.Bytes(), &res) == nil {
		resp.HostDir = s.relPath(res.OutputDir)
		resp.System = res.System.Name
		for _, c := range res.System.Components {
			resp.Added = append(resp.Added, c.AppID)
		}
	}
	writeJSON(w, http.StatusOK, resp)
}

// resolveSystemDir confines a root-relative system path to the workspace,
// under the same segment rules a create request's dir obeys; "" and "."
// mean the workspace root itself. The directory must exist — the endpoint
// syncs systems, it does not invent them.
func (s *apiServer) resolveSystemDir(rel string) (string, error) {
	segments, err := splitCreateDir(rel)
	if err != nil {
		return "", err
	}
	dir := filepath.Join(append([]string{s.root}, segments...)...)
	if info, statErr := os.Stat(dir); statErr != nil || !info.IsDir() {
		return "", fmt.Errorf("directory %q does not exist under the workspace root", rel)
	}
	return dir, nil
}

// hostSystemName names a system created for dir after the directory itself,
// resolved to absolute first so the workspace root ("." from a relative
// invocation) still yields its folder name.
func hostSystemName(dir string) string {
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// syncErrorStatus maps a host sync failure onto the status the banner acts
// on: a divergence the command refuses to overwrite is a 409 (the retry
// offers force), a workspace-shape problem is a 422, and an upstream
// template fetch failure is a 502.
func syncErrorStatus(err error) int {
	msg := err.Error()
	switch {
	case strings.Contains(msg, "--force"), strings.Contains(msg, "not empty"):
		return http.StatusConflict
	case strings.Contains(msg, "fetch"), strings.Contains(msg, "download"):
		return http.StatusBadGateway
	case strings.Contains(msg, "system host"),
		strings.Contains(msg, "not a workspace"),
		strings.Contains(msg, "scaffold"),
		strings.Contains(msg, "component"):
		return http.StatusUnprocessableEntity
	}
	return http.StatusInternalServerError
}
