package dashboard

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
// the detail endpoint returns, so a huge file cannot bloat a response.
const maxDocBytes = 128 * 1024

// providers are the request-independent sources the API reads beyond the
// workspace's own files: what a system host declares about its topology, and
// what the GitOps repository says is deployed. Both run a command, so both are
// injected as function values that tests replace. templates is a value, not a
// function: it carries configuration (release pin, test overrides), not a
// stubbed behavior — tests override its fields instead.
type providers struct {
	topology  topologyProvider
	deploy    deployProvider
	templates templatesProvider
}

// deployStateTimeout bounds one deploy status run.
//
// It exists for the checkout lock rather than for the browser: the command holds
// an exclusive lock on the shared GitOps checkout for its whole duration, and an
// ArgoCD server that accepts connections but never answers would otherwise keep
// that lock — blocking the user's own intropy deploy indefinitely. A minute is
// generous for a fetch plus a handful of ArgoCD calls and short enough that a
// hung one lets go.
const deployStateTimeout = time.Minute

// apiServer holds the request-independent state for the JSON API.
type apiServer struct {
	root      string
	version   string
	topo      topologyProvider
	dep       deployProvider
	templates templatesProvider

	// organization is the resolved config's customer, seeded into
	// workspace facts as the ambient organization default when the
	// workspace's own records name none.
	organization string

	// createMu serializes template create runs: two concurrent renders of the
	// same name would race on the output directory, and a cold cache would have
	// both cloning the library. The same bargain depMu makes for its checkout.
	createMu sync.Mutex

	// tagMu guards the resolved template library release. Resolving it costs a
	// GitHub API call, so it is resolved on the first template request and held
	// for the life of the process: the form and the run it starts then render
	// from one release by construction, and a form's per-keystroke suggestion
	// refreshes cost nothing. An explicit refresh re-resolves.
	tagMu sync.Mutex
	tag   string

	// topoMu guards the cached provider result. Fetching runs the hosts'
	// graph verbs (a dotnet build on first run), so the result is computed
	// once — on the first /api/topology request — and reused until an
	// explicit refresh.
	topoMu      sync.Mutex
	topoLoaded  bool
	topoWarming bool
	topoEntries []topology.Entry
	topoErrs    []string

	// depMu guards the cached deployment state, keyed by root-relative path.
	// Reading it refreshes a shared GitOps checkout under an exclusive lock, so
	// unlike the topology this is cached per integration and computed only for
	// the ones actually asked about.
	depMu     sync.Mutex
	depStates map[string]deployState

	// runMu guards the supervised system hosts, keyed by root-relative system
	// dir. start launches through the start function value (dotnet run in
	// production, a fake in tests — the same seam providers uses).
	runMu sync.Mutex
	runs  map[string]*systemRun
	start starter
}

// topologyReport is the /api/topology payload: every declared topology plus
// the per-host failures the UI renders. Topologies is always an array (never
// null) even when empty.
type topologyReport struct {
	Topologies []topologyEntry `json:"topologies"`
	Errors     []string        `json:"errors,omitempty"`
}

// topologyEntry is one system's declared topology plus the authored
// enrichment read from its directory: message descriptions keyed by port
// name. The docs ride beside the Topology rather than inside it — the
// topology stays exactly what the host declared.
type topologyEntry struct {
	topology.Entry
	MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
}

// fileDoc is a text document surfaced in an integration's detail view.
type fileDoc struct {
	Name    string `json:"name"`
	Content string `json:"content"`
}

// integrationSummary is a scaffold entry plus the coordinates the sidebar
// tree groups by: Name is the directory that carries the .intropy record.
// System is the name a sibling system-host scaffold declares for the
// directory's parent, falling back to the parent folder's name; Domain is the
// system's parent folder. Absent a host, System is empty when the integration
// sits directly under the workspace root, and Domain is empty when the
// system does.
type integrationSummary struct {
	template.ScaffoldEntry
	Name   string `json:"name"`
	System string `json:"system,omitempty"`
	Domain string `json:"domain,omitempty"`
	// SystemPath is the root-relative directory of the system the integration
	// belongs to ("." when the system is rooted at the workspace itself).
	// Unlike System — a declared name two directories can share — it is a
	// unique grouping key, and it matches the `path` of the topology record
	// the system's host produces. Absent when the integration has no system.
	SystemPath string `json:"systemPath,omitempty"`
}

// integrationDetail is a single integration plus best-effort, on-disk
// enrichment. Every enrichment field is optional and absent when the
// corresponding file or directory does not exist.
type integrationDetail struct {
	integrationSummary
	Agents        *fileDoc        `json:"agents,omitempty"`
	Readme        *fileDoc        `json:"readme,omitempty"`
	Components    []DaprComponent `json:"components,omitempty"`
	PipelineSteps []string        `json:"pipelineSteps,omitempty"`
}

// newHandler wires the API routes and the SPA static handler onto a mux and
// returns the apiServer alongside: Serve needs its shutdownRuns (stopping the
// supervised system hosts after the HTTP server drains) and tests need its
// start seam.
func newHandler(root, version string, p providers) (http.Handler, *apiServer, error) {
	api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy, templates: p.templates, start: dotnetStart}
	static, err := staticHandler()
	if err != nil {
		return nil, nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/health", api.health)
	mux.HandleFunc("GET /api/integrations", api.listIntegrations)
	mux.HandleFunc("GET /api/systems", api.listSystems)
	// GET lists what is declared; POST re-assembles one system's host
	// (sys update, or sys create when the directory has none).
	mux.HandleFunc("POST /api/systems/{path...}", api.syncSystem)
	mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
	mux.HandleFunc("GET /api/catalog/{path...}", api.catalog)
	mux.HandleFunc("GET /api/flow", api.flow)
	mux.HandleFunc("GET /api/topology", api.topologies)
	mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
	// The verb carries the meaning rather than a /refresh segment: a {path...}
	// wildcard has to be the last thing in the pattern. GET serves what has
	// already been read, POST runs the command again.
	mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
	mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
	// Run supervision: the flow view's start/stop for a system's host. A
	// dedicated prefix — ServeMux forbids a {path...} wildcard mid-pattern, so
	// /api/systems/{path...}/run cannot exist. The workspace-root system
	// arrives as "" (ServeMux redirects /api/run/. to /api/run/) and the
	// handlers normalize it to ".", the same rule byPath applies.
	mux.HandleFunc("GET /api/run/{path...}", api.getRun)
	mux.HandleFunc("POST /api/run/{path...}", api.startRun)
	mux.HandleFunc("DELETE /api/run/{path...}", api.stopRun)
	// Template endpoints follow the same GET-read / POST-act split: list and
	// show fetch the library release, create renders into the workspace.
	mux.HandleFunc("GET /api/templates", api.listTemplates)
	mux.HandleFunc("POST /api/templates/refresh", api.refreshTemplates)
	mux.HandleFunc("GET /api/templates/{name}", api.getTemplate)
	// Registered before {name} so "suggestions" binds to the literal.
	mux.HandleFunc("GET /api/templates/suggestions/{name}", api.getTemplateSuggestions)
	mux.HandleFunc("POST /api/templates/{name}/create", api.createTemplate)
	// Test-file seeding: GET lists one system's testdata/<port>/ library,
	// POST copies a chosen file into the port's dev inbox. The GET's
	// {path...} wildcard is the root-relative system path.
	mux.HandleFunc("GET /api/testdata/{path...}", api.listTestData)
	mux.HandleFunc("POST /api/seed", api.seedTestFile)
	mux.Handle("/", static)
	return mux, api, nil
}

func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{
		"status":    "ok",
		"version":   s.version,
		"workspace": s.workspaceName(),
	})
}

// workspaceName is the served root's directory name — the label the flow
// view gives the workspace pseudo-system, so a dashboard on ~/dev/acme says
// "acme" rather than a generic "Workspace". Serve hands the handler an
// absolute root; the extra Abs covers callers (tests) that pass a relative
// one, where Base would otherwise answer ".".
func (s *apiServer) workspaceName() string {
	root := s.root
	if abs, err := filepath.Abs(root); err == nil {
		root = abs
	}
	return filepath.Base(root)
}

// listIntegrations mirrors `int list -o json` — the same scaffold entries in
// the same order — with the derived name/system fields added on top and each
// Path normalized to a root-relative identifier. The response is always an
// array (never null) even when empty.
func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	summaries := make([]integrationSummary, 0, len(entries))
	for _, e := range entries {
		summaries = append(summaries, s.summarize(e, systems))
	}
	writeJSON(w, http.StatusOK, summaries)
}

// systemInfo is one declared system: the directory holding a system-host
// scaffold, root-relative, plus the name the host declares.
type systemInfo struct {
	Path string `json:"path"`
	Name string `json:"name"`
}

// listSystems reports every declared system, so the flow view can offer a
// system that has a host but no blocks yet — /api/flow only carries systems
// through the blocks that belong to them. The response is always an array
// (never null) even when empty.
func (s *apiServer) listSystems(w http.ResponseWriter, _ *http.Request) {
	_, systems := s.scan()
	out := make([]systemInfo, 0, len(systems))
	for dir, name := range systems {
		out = append(out, systemInfo{Path: s.relPath(dir), Name: name})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Path < out[j].Path })
	writeJSON(w, http.StatusOK, out)
}

// scan splits the workspace's scaffold entries for the API: the integration
// blocks to catalog, plus the declared systems keyed by their root directory
// (the directory holding a system-host scaffold). Support projects — the host
// and its shared contracts library — are infrastructure the system view
// already represents, not integrations to list.
func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
	entries, _ := template.ListScaffolds(s.root)
	systems = map[string]string{}
	for _, e := range entries {
		if e.Role == template.RoleSystemHost {
			systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
		}
	}
	blocks = entries[:0]
	for _, e := range entries {
		if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
			continue
		}
		blocks = append(blocks, e)
	}
	return blocks, systems
}

// systemName is the name a system-host scaffold declares for its system
// (the template's `name` value, recorded at `sys create`), falling back to
// the host's parent directory name.
func systemName(host template.ScaffoldEntry) string {
	if name, ok := template.SoftValue(host.Values, template.KeyName); ok {
		return name
	}
	dir := filepath.Dir(host.Path)
	if abs, err := filepath.Abs(dir); err == nil {
		dir = abs
	}
	return filepath.Base(dir)
}

// summarize derives an entry's tree coordinates from its path and the
// declared systems. A sibling system-host makes membership explicit: its
// declared name wins over the folder-derived one and applies even directly
// under the workspace root (where no folder-derived system exists).
// Otherwise the workspace root itself never counts as a system or domain, so
// an integration scaffolded at the root has neither and one directly under
// the root has a system but no domain. The served Path is made root-relative
// so it is a stable, URL-safe identifier regardless of whether the command
// was given a relative or absolute root (an absolute path would otherwise
// break detail lookups).
func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
	sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
	sum.Path = s.relPath(e.Path)
	path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
	parent := filepath.Dir(path)
	if declared, ok := systems[parent]; ok && path != root {
		sum.System = declared
		sum.SystemPath = s.relPath(parent)
		if grand := filepath.Dir(parent); parent != root && grand != root {
			sum.Domain = filepath.Base(grand)
		}
		return sum
	}
	if path == root || parent == root {
		return sum
	}
	sum.System = filepath.Base(parent)
	sum.SystemPath = s.relPath(parent)
	if grand := filepath.Dir(parent); grand != root {
		sum.Domain = filepath.Base(grand)
	}
	return sum
}

// relPath turns an entry's on-disk path into the root-relative, slash-separated
// identifier used in API responses and URLs. It falls back to the cleaned path
// so a value is always produced even if Rel fails (e.g. differing volumes).
func (s *apiServer) relPath(p string) string {
	if rel, err := filepath.Rel(s.root, p); err == nil {
		return filepath.ToSlash(rel)
	}
	return filepath.ToSlash(filepath.Clean(p))
}

// flow returns every integration enriched with the pipeline steps and Dapr
// components the flow canvas draws, so the whole graph loads in one request.
// It reuses integrationDetail but leaves the document fields (agents/readme)
// nil — the canvas nodes do not render them.
func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
	entries, systems := s.scan()
	nodes := make([]integrationDetail, 0, len(entries))
	for _, e := range entries {
		dir := e.Path
		nodes = append(nodes, integrationDetail{
			integrationSummary: s.summarize(e, systems),
			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
		})
	}
	writeJSON(w, http.StatusOK, nodes)
}

// topologies returns every system topology declared by a host's graph verb,
// each Path normalized to the same root-relative identifier integration
// paths use, so the flow canvas can match a topology to the integrations
// living beside its host. The provider result is cached after the first
// request (the verb builds the host); POST /api/topology/refresh recomputes.
func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
}

// refreshTopologies recomputes the topology cache by re-running every host's
// graph verb, then returns the fresh report.
func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
}

// topologyReport assembles the /api/topology payload: the cached provider
// result plus the message docs read fresh from disk on every request, so an
// edited doc shows up on a browser refresh without re-running the hosts'
// graph verbs.
func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
	entries, errs := s.cachedTopologies(ctx, force)
	report := topologyReport{
		Topologies: make([]topologyEntry, 0, len(entries)),
		Errors:     append([]string(nil), errs...),
	}
	for _, e := range entries {
		docs, docErrs := s.messageDocs(e)
		report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
		report.Errors = append(report.Errors, docErrs...)
	}
	return report
}

// cachedTopologies returns the provider result — computed on first use or
// when force is set, reused otherwise. Concurrent requests share one
// computation. Entry paths are normalized to root-relative identifiers.
func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	if !s.topoLoaded || force {
		entries, errs := s.topo(ctx)
		s.topoEntries = make([]topology.Entry, 0, len(entries))
		for _, e := range entries {
			e.Path = s.relPath(e.Path)
			s.topoEntries = append(s.topoEntries, e)
		}
		s.topoErrs, s.topoLoaded = errs, true
	}
	return s.topoEntries, s.topoErrs
}

// topologiesLoaded reports whether the topology cache has been computed, and
// serves the cached result if it has. It never blocks on the computation:
// computing runs every host's graph verb (a dotnet build on first run) under
// one mutex, and the catalog endpoint must answer promptly rather than queue
// behind that. Instead the caller asks warmTopologies to compute in the
// background, so the pending answer becomes a matched one on the next fetch
// without anyone visiting the flow view first.
func (s *apiServer) topologiesLoaded() (loaded bool, entries []topology.Entry, errs []string) {
	s.topoMu.Lock()
	defer s.topoMu.Unlock()
	return s.topoLoaded, s.topoEntries, s.topoErrs
}

// warmTopologies triggers the topology computation in the background when the
// cache is cold. Only one warm-up runs at a time — cachedTopologies
// serialises on topoMu, and warming guards against stacking requests behind
// it. A detached context keeps the hosts' graph verbs running after the
// request that prompted them has been answered.
func (s *apiServer) warmTopologies() {
	s.topoMu.Lock()
	if s.topoLoaded || s.topoWarming {
		s.topoMu.Unlock()
		return
	}
	s.topoWarming = true
	s.topoMu.Unlock()

	go func() {
		defer func() {
			s.topoMu.Lock()
			s.topoWarming = false
			s.topoMu.Unlock()
		}()
		// The catalog requests that triggered this are already answered; the
		// computation is for the next one.
		_, _ = s.cachedTopologies(context.Background(), false)
	}()
}

// messageDocs reads the authored port payload descriptions beside a system,
// keyed by port name. A doc naming a port the topology does not declare is
// surfaced as an error and withheld — never guessed around. Error messages
// carry the doc's workspace-relative path.
func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
	docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
	prefix := ""
	if e.Path != "." {
		prefix = e.Path + "/"
	}
	for i, msg := range errs {
		errs[i] = prefix + msg
	}
	known := map[string]bool{}
	for _, c := range e.Ports {
		known[c.Name] = true
	}
	var unknown []string
	for name := range docs {
		if !known[name] {
			unknown = append(unknown, name)
			delete(docs, name)
		}
	}
	sort.Strings(unknown)
	for _, name := range unknown {
		errs = append(errs, fmt.Sprintf("%s%s/%s.md: no port %q declared by system %q",
			prefix, messagesDirName, name, name, e.System))
	}
	if len(docs) == 0 {
		docs = nil
	}
	return docs, errs
}

func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.enrich(e, systems)
	})
}

// getDeployState serves what the deploy status command last said about one
// integration, running it on the first request and reusing that until a POST to
// the same path. It is a separate endpoint from the integration detail because
// the two cost very different things: detail is local files, this refreshes a
// GitOps checkout over the network. Keeping them apart lets the detail panel
// render immediately and fill the deployment in when it arrives.
func (s *apiServer) getDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, false)
}

// refreshDeployState re-runs the command for one integration and returns the
// fresh result, picking up a deploy someone just made from another terminal.
func (s *apiServer) refreshDeployState(w http.ResponseWriter, r *http.Request) {
	s.deployStateByPath(w, r, true)
}

func (s *apiServer) deployStateByPath(w http.ResponseWriter, r *http.Request, force bool) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		return s.cachedDeployState(r.Context(), s.summarize(e, systems), force)
	})
}

// byPath resolves the {path...} wildcard to a scaffolded integration and serves
// what render makes of it, or 404s. Shared so the detail and deployment
// endpoints agree about which identifiers name the same integration.
func (s *apiServer) byPath(w http.ResponseWriter, r *http.Request, render func(template.ScaffoldEntry, map[string]string) any) {
	want := strings.Trim(r.PathValue("path"), "/")
	// An integration at the workspace root has the identifier "." (see
	// relPath), but a browser strips the "." segment from /api/integrations/.
	// so it arrives empty — treat the two as the same request.
	if want == "" {
		want = "."
	}
	entries, systems := s.scan()
	for _, e := range entries {
		if s.relPath(e.Path) == want {
			writeJSON(w, http.StatusOK, render(e, systems))
			return
		}
	}
	writeError(w, http.StatusNotFound, "integration not found: "+want)
}

// cachedDeployState returns one integration's deployment state — computed on
// first use or when force is set, reused otherwise.
//
// The mutex is held across the provider call rather than only around the map,
// because the command takes an exclusive lock on the shared GitOps checkout:
// two requests running it at once would have one of them fail on the other's
// lock. Serialising here turns that failure into a wait, and concurrent requests
// for the same integration share one run — the same bargain cachedTopologies
// makes with topoMu.
func (s *apiServer) cachedDeployState(ctx context.Context, sum integrationSummary, force bool) deployState {
	s.depMu.Lock()
	defer s.depMu.Unlock()

	if state, ok := s.depStates[sum.Path]; ok && !force {
		return state
	}

	ctx, cancel := context.WithTimeout(ctx, deployStateTimeout)
	defer cancel()
	state := s.dep(ctx, sum)

	if s.depStates == nil {
		s.depStates = map[string]deployState{}
	}
	s.depStates[sum.Path] = state
	return state
}

// enrich reads optional on-disk context for an integration. The entry's Path
// is already usable from the process working directory (see ListScaffolds), so
// it doubles as the project directory.
func (s *

package dashboard

import (
	"fmt"
	"net/http"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// Graph status values CatalogEntry.GraphStatus takes.
const (
	graphMatched       = "matched"
	graphNoTopology    = "no-topology"
	graphNotInGraph    = "not-in-graph"
	graphTopologyError = "topology-error"
	graphPending       = "pending"
)

// Check severity values.
const (
	severityWarn = "warn"
	severityInfo = "info"
)

// CatalogEntry is the /api/catalog/{path} payload: the integration's header
// facts and its checks, assembled from the cached topology report and the
// scaffold walk. Deployment state is NOT embedded — it stays on
// /api/deploy/{path}, which costs a GitOps checkout refresh.
type CatalogEntry struct {
	// Component is the header identity: the graph's name for the component
	// when GraphStatus is "matched", the scaffold record's name otherwise.
	Component string `json:"component"`

	// Kind is the topology block kind. Empty in every non-matched state.
	Kind string `json:"kind,omitempty"`

	// System is the declared system name, when the integration has one.
	System string `json:"system,omitempty"`

	// SystemPath is the system directory the topology record joins on. It
	// travels so a consumer fetching the topology (for the contract registry,
	// which this payload does not embed) can match the right system.
	SystemPath string `json:"systemPath,omitempty"`

	// Contracts the component publishes/subscribes on, resolved against the
	// topology's contracts registry. Absent in every non-matched state.
	Publishes  []ContractEdge `json:"publishes,omitempty"`
	Subscribes []ContractEdge `json:"subscribes,omitempty"`

	// Repository is "owner/repo" from the scaffold record — provenance only.
	// The record can go stale, so identity and contracts come from the graph.
	Repository string `json:"repository,omitempty"`

	// GraphStatus: "matched" | "no-topology" | "not-in-graph" |
	// "topology-error" | "pending".
	GraphStatus string `json:"graphStatus"`

	// TopologyPending is true while the first topology computation is in
	// flight. The header renders from scaffold data; contracts are unknown.
	TopologyPending bool `json:"topologyPending,omitempty"`

	// Checks are graph-derived findings, warns before infos.
	Checks []Check `json:"checks,omitempty"`
}

// ContractEdge is one end of a pub/sub wire a component sits on.
type ContractEdge struct {
	Pubsub string `json:"pubsub"`
	Topic  string `json:"topic"`

	// Contract is the topic's contract shortName when the registry carries it,
	// and the topic's raw contract name otherwise — the same lookup the flow
	// view's detail panel makes.
	Contract string `json:"contract,omitempty"`

	// Publishers and Subscribers are every component the topic declares on each
	// end of the wire, so a contract can be inspected as the connection between
	// components rather than as a name. Absent when the topic declares neither.
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Check is one finding about the integration's place in the system graph.
type Check struct {
	// Severity: "warn" | "info".
	Severity string `json:"severity"`
	Message  string `json:"message"`
}

// catalog serves one integration's catalog entry: header identity and
// contracts from the cached topology report when it has the component, from
// the scaffold record otherwise. It never triggers the topology computation —
// the flow view owns that cost — so a request against a cold cache answers
// promptly with the component pending.
func (s *apiServer) catalog(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		sum := s.summarize(e, systems)
		loaded, entries, errs := s.topologiesLoaded()
		if !loaded {
			// Answer pending now, compute in the background: the pending answer
			// becomes a matched one on the next fetch, without the request
			// queueing behind a dotnet build per host.
			s.warmTopologies()
		}
		return buildCatalogEntry(sum, systems, loaded, entries, errs)
	})
}

// buildCatalogEntry joins the scaffold summary to the cached topology report.
// Separated from the handler so tests exercise the join without HTTP.
func buildCatalogEntry(sum integrationSummary, systems map[string]string, loaded bool, entries []topology.Entry, errs []string) CatalogEntry {
	entry := CatalogEntry{
		Component:  sum.Name,
		System:     sum.System,
		SystemPath: sum.SystemPath,
		Repository: sum.Owner + "/" + sum.Repo,
	}

	// A request against a cold cache answers promptly with scaffold identity
	// rather than queueing behind a dotnet build per host.
	if !loaded {
		entry.GraphStatus = graphPending
		entry.TopologyPending = true
		return entry
	}

	if sum.SystemPath == "" {
		entry.GraphStatus = graphNoTopology
		return entry
	}

	topo, hostErr := findTopology(entries, errs, sum.SystemPath)
	switch {
	case hostErr != "":
		entry.GraphStatus = graphTopologyError
		entry.Checks = appendCheck(entry.Checks, Check{Severity: severityInfo, Message: hostErr})
	case topo == nil:
		entry.GraphStatus = graphNoTopology
	default:
		joinTopology(&entry, sum, topo, systemDeclared(systems, sum))
	}
	return entry
}

// findTopology looks up the cached record for a system path, reporting the
// host's own error message when its graph verb failed. The per-host error
// strings the provider produces are prefixed with the system directory they
// ran in, which is the same identifier space the entry paths use.
func findTopology(entries []topology.Entry, errs []string, systemPath string) (*topology.Entry, string) {
	for i := range entries {
		if entries[i].Path == systemPath {
			return &entries[i], ""
		}
	}
	return nil, hostError(errs, systemPath)
}

func hostError(errs []string, systemPath string) string {
	prefix := systemPath + ": "
	for _, err := range errs {
		if strings.HasPrefix(err, prefix) {
			return err
		}
	}
	return ""
}

// systemDeclared reports whether the integration's system membership comes
// from a sibling system-host scaffold rather than from folder convention. Only
// a declared host justifies a drift warning when the component is absent from
// the graph: a folder-derived "system" is a normal workspace state, not a
// promise that a graph exists.
func systemDeclared(systems map[string]string, sum integrationSummary) bool {
	parent := filepath.Clean(filepath.Dir(sum.ScaffoldEntry.Path))
	_, ok := systems[parent]
	return ok
}

// joinTopology resolves the component against its system's declared graph.
// The join is by directory name: a component's directory is its Name relative
// to the system root.
func joinTopology(entry *CatalogEntry, sum integrationSummary, topo *topology.Entry, declared bool) {
	var comp *topology.Component
	for i := range topo.Components {
		if topo.Components[i].Name == sum.Name {
			comp = &topo.Components[i]
			break
		}
	}
	if comp == nil {
		if !declared {
			// The folder looked like a system but no host declared one, so
			// there is no graph to be absent from — nothing to warn about.
			entry.GraphStatus = graphNoTopology
			return
		}
		entry.GraphStatus = graphNotInGraph
		entry.Checks = appendCheck(entry.Checks, Check{
			Severity: severityWarn,
			Message:  fmt.Sprintf("the system graph does not declare a component named %s — renamed without re-scaffolding?", sum.Name),
		})
		return
	}

	entry.GraphStatus = graphMatched
	entry.Component = comp.Name
	entry.Kind = comp.Kind
	for _, p := range comp.Publishes {
		entry.Publishes = append(entry.Publishes, contractEdge(topo, p.PubSub, p.Topic))
	}
	for _, sub := range comp.Subscribes {
		entry.Subscribes = append(entry.Subscribes, contractEdge(topo, sub.PubSub, sub.Topic))
	}
}

// appendCheck keeps the slice severity-ordered: warns before infos.
func appendCheck(checks []Check, c Check) []Check {
	if c.Severity != severityWarn {
		return append(checks, c)
	}
	n := 0
	for n < len(checks) && checks[n].Severity == severityWarn {
		n++
	}
	return append(checks[:n], append([]Check{c}, checks[n:]...)...)
}

// contractEdge resolves one (pubsub, topic) reference against the topology's
// topics and contracts registry: the contract is the registry entry's
// shortName when the topic names a contract and the registry carries it, and
// the raw contract name otherwise — the same lookup the flow view makes. The
// topic's declared publishers and subscribers ride along, so a contract can
// be shown as the connection between components rather than as a name.
func contractEdge(topo *topology.Entry, pubsub, topic string) ContractEdge {
	edge := ContractEdge{Pubsub: pubsub, Topic: topic}
	for _, t := range topo.Topics {
		if t.PubSub != pubsub || t.Topic != topic {
			continue
		}
		edge.Publishers = t.Publishers
		edge.Subscribers = t.Subscribers
		if t.Contract == "" {
			break
		}
		edge.Contract = t.Contract
		for _, c := range topo.Contracts {
			if c.Name == t.Contract && c.ShortName != "" {
				edge.Contract = c.ShortName
				break
			}
		}
		break
	}
	return edge
}

// buildDeclaredGraph renders a system's declared topology (v1): components and
// the topics they publish/subscribe laid out left-to-right by flow depth
// inside the boundary, external systems (via ports) outside it. Nothing
// here is inferred — every node and edge comes straight from the record's
// inline wiring.
function buildDeclaredGraph(
  topo: Topology,
  items: IntegrationDetail[],
): { nodes: Node[]; edges: Edge[]; ghosts: IntegrationDetail[] } {
  const comps = topo.components ?? []

  // Metadata lookups: topics carry the contract, ports the external
  // system a component's inline reference resolves against.
  const topicMeta = new Map(
    (topo.topics ?? []).map((t) => [`${t.pubsub}/${t.topic}`, t]),
  )
  const portMeta = new Map((topo.ports ?? []).map((c) => [c.name, c]))

  // A topic node is identified by its (pubsub, topic) pair; a component by ref.
  const topicId = (pubsub: string, topic: string): string => `topic:${pubsub}/${topic}`

  // Map component refs to integration paths so clicking a declared node
  // selects the scaffolded integration when one exists. The declared name is
  // the component's appId, and the scaffold record's appId is the same value
  // — the directory name is not, since a scaffold can be rendered under a
  // folder that differs from its --name. The path-shaped fallback keeps
  // matching scaffolds whose record predates the appId value.
  const joinProject = (base: string, project: string): string => {
    if (project === '.' || project === '') return base
    return base === '.' ? project : `${base}/${project}`
  }
  const byAppId = new Map<string, string>()
  for (const it of items) {
    const appId = it.values?.appId
    if (typeof appId === 'string' && appId !== '') byAppId.set(appId, it.path)
  }
  const scaffoldPath = (name: string): string | undefined =>
    byAppId.get(name) ??
    (items.some((it) => it.path === joinProject(topo.path, name))
      ? joinProject(topo.path, name)
      : undefined)
  const nodeId = new Map<string, string>()
  for (const c of comps) {
    nodeId.set(`component:${c.name}`, scaffoldPath(c.name) ?? `component:${c.name}`)
  }

  // Collect the unique topics the components reference, and the internal flow
  // edges (component ⇄ topic) that decide layout depth.
  const topicRefs = new Map<string, { pubsub: string; topic: string }>()
  const flowEdges: Array<{ from: string; to: string }> = []
  for (const c of comps) {
    const cref = `component:${c.name}`
    for (const p of c.publishes ?? []) {
      const tid = topicId(p.pubsub, p.topic)
      topicRefs.set(tid, { pubsub: p.pubsub, topic: p.topic })
      flowEdges.push({ from: cref, to: tid })
    }
    for (const s of c.subscribes ?? []) {
      const tid = topicId(s.pubsub, s.topic)
      topicRefs.set(tid, { pubsub: s.pubsub, topic: s.topic })
      flowEdges.push({ from: tid, to: cref })
    }
  }
  for (const tid of topicRefs.keys()) nodeId.set(tid, tid)

  // Longest-path layering over the internal flow edges decides each node's
  // column. Kahn-style relaxation; anything left by a cycle lands in column 0
  // rather than failing the render.
  const internal = new Set<string>([
    ...comps.map((c) => `component:${c.name}`),
    ...topicRefs.keys(),
  ])
  const succ = new Map<string, string[]>()
  const indeg = new Map<string, number>()
  for (const r of internal) {
    succ.set(r, [])
    indeg.set(r, 0)
  }
  for (const e of flowEdges) {
    if (!internal.has(e.from) || !internal.has(e.to)) continue
    succ.get(e.from)?.push(e.to)
    indeg.set(e.to, (indeg.get(e.to) ?? 0) + 1)
  }
  const depth = new Map<string, number>()
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  // At least three columns, so the create slots always sit in their archetype
  // positions (in → process → out) even when the declared graph is narrower —
  // an empty system renders as the fillable three-slot skeleton.
  const effCols = Math.max(cols, 3)
  const extractorCol = 0
  const loaderCol = Math.max(2, cols - 1)
  const transactionalCol = Math.min(loaderCol - 1, Math.max(1, Math.round(loaderCol / 2)))
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + effCols * NODE_W + (effCols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'

  // Scaffolded-but-undeclared components: blocks whose scaffold record lives
  // in this system but whose name the declared topology does not carry —
  // brand new (pre `sys create`) or renamed. They render as ghosts in their
  // block kind's column, wireless, until the host declares them.
  const declaredPaths = new Set(
    comps.map((c) => scaffoldPath(c.name) ?? joinProject(topo.path, c.name)),
  )
  const ghosts = items.filter((it) => !declaredPaths.has(it.path))
  const ghostCol = (g: IntegrationDetail): number => {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    return flow === 'in' ? extractorCol : flow === 'out' ? loaderCol : transactionalCol
  }

  // Placeholder slots — one per kind column, pinned to a shared bottom rail
  // below the flow. Clicking one opens the create drawer pre-filtered to
  // that block kind; the slots are affordances, never part of the graph.
  const slotDefs: Array<{ kind: SlotKind; col: number }> = [
    { kind: 'extractor', col: extractorCol },
    { kind: 'transactional', col: transactionalCol },
    { kind: 'loader', col: loaderCol },
  ]

  // Column stacks center vertically against the tallest column: a lone
  // extractor sits level with the middle of the loader stack (and the topic
  // centered between them) instead of hugging the top, and the stack grows
  // out from the middle as blocks are added. Centering needs each column's
  // row count up front — the stack's height decides its starting offset.
  // Slots never count: they pin to the bottom rail (below), so they must not
  // push their column's stack off centre.
  const colRows: number[] = new Array<number>(effCols).fill(0)
  for (const c of comps) colRows[depth.get(`component:${c.name}`) ?? 0]++
  for (const [tid] of topicRefs) colRows[depth.get(tid) ?? 0]++
  for (const g of ghosts) colRows[ghostCol(g)]++
  const maxRows = Math.max(1, ...colRows)

  const rowsInCol: number[] = new Array<number>(effCols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    const offset = ((maxRows - colRows[d]) * (NODE_H + ROW_GAP)) / 2
    return { x: colX(d), y: contentTop + offset + row * (NODE_H + ROW_GAP), row }
  }

  // Component positions, keyed by ref, so externals can anchor to the
  // component they touch instead of the far edge of the canvas.
  const compPos = new Map<string, { x: number; y: number; col: number }>()
  for (const c of comps) {
    const ref = `component:${c.name}`
    const col = depth.get(ref) ?? 0
    const pos = place(col)
    compPos.set(ref, { x: pos.x, y: pos.y, col })
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.kind,
        dataFlow: dataFlowFor(c.kind),
        selected: false,
      } satisfies IntNodeData,
    })
  }

  // Vertical centering per topic: the average card-centre y of the
  // components wired to it, minus the topic's own half height. A topic's
  // place is between its publisher and subscribers, not on a row of its own.
  const topicY = new Map<string, number>()
  for (const [tid] of topicRefs) {
    const neighbours = comps
      .filter(
        (c) =>
          (c.publishes ?? []).some((p) => topicId(p.pubsub, p.topic) === tid) ||
          (c.subscribes ?? []).some((s) => topicId(s.pubsub, s.topic) === tid),
      )
      .map((c) => compPos.get(`component:${c.name}`))
      .filter((p): p is { x: number; y: number; col: number } => p !== undefined)
    if (neighbours.length === 0) continue
    const centre =
      neighbours.reduce((sum, p) => sum + p.y + NODE_H / 2, 0) / neighbours.length
    topicY.set(tid, centre - INFRA_H / 2)
  }

  for (const [tid, ref] of topicRefs) {
    const pos = place(depth.get(tid) ?? 0)
    const meta = topicMeta.get(`${ref.pubsub}/${ref.topic}`)
    nodes.push({
      id: nodeId.get(tid)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      // Rows share them across the topic's neighbours, so centre vertically
      // on the average of the wired components rather than taking the row.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: topicY.get(tid) ?? pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: ref.topic,
        pubsub: ref.pubsub,
        contract: meta?.contract,
      } satisfies TopicNodeData,
    })
  }

  for (const g of ghosts) {
    const flow = g.dataFlow ?? (g.blockKind ? dataFlowFor(g.blockKind) : undefined)
    const pos = place(ghostCol(g))
    nodes.push({
      id: g.path,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: g.name,
        template: g.blockKind || g.template,
        dataFlow: flow,
        selected: false,
        ghost: true,
      } satisfies IntNodeData,
    })
  }

  // The slot rail: one shared baseline below the deepest node, so the slots
  // align across columns instead of drifting with each column's stack. An
  // empty system has no node bottom — the rail is the content top.
  const nodeBottom = Math.max(
    0,
    ...colRows.map((rows) =>
      rows === 0
        ? 0
        : contentTop +
          ((maxRows - rows) * (NODE_H + ROW_GAP)) / 2 +
          (rows - 1) * (NODE_H + ROW_GAP) +
          NODE_H,
    ),
  )
  const slotY = nodeBottom === 0 ? contentTop : nodeBottom + ROW_GAP
  for (const s of slotDefs) {
    nodes.push({
      id: `slot:${s.kind}`,
      type: 'slot',
      parentId: groupId,
      extent: 'parent',
      position: { x: colX(s.col), y: slotY },
      style: { width: NODE_W, height: NODE_H },
      draggable: false,
      selectable: false,
      data: { kind: s.kind } satisfies SlotNodeData,
    })
  }

  const groupHeight = slotY + NODE_H + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system, count: comps.length + ghosts.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Topic publish/subscribe edges. A publish leaves the component's right
  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')

  // ('ext') handle for the topic; a subscribe leaves the topic's right ('out')
  // handle for the subscriber.
  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    for (const p of c.publishes ?? []) {
      const target = nodeId.get(topicId(p.pubsub, p.topic))
      if (!target) continue
      edges.push({
        id: `e:pub:${c.name}:${p.pubsub}/${p.topic}`,
        source: comp,
        sourceHandle: 'ext',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
    for (const s of c.subscribes ?? []) {
      const source = nodeId.get(topicId(s.pubsub, s.topic))
      if (!source) continue
      edges.push({
        id: `e:sub:${s.pubsub}/${s.topic}:${c.name}`,
        source,
        sourceHandle: 'out',
        target: comp,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
    }
  }

  // Externals sit outside the boundary: a source (input port) directly left
  // of its component, a destination (output port) on a rail off the
  // boundary's right edge, aligned with its component's row and bumped down
  // when rows collide. Sources flow in on the left, destinations out on the
  // right — the same in → process → out reading as the columns inside.
  const railX = groupWidth + EXT_GAP
  const railYs: number[] = []
  const railY = (want: number): number => {
    let y = want
    while (railYs.some((used) => Math.abs(used - y) < EXT_H + EXT_VGAP)) {
      y += EXT_H + EXT_VGAP
    }
    railYs.push(y)
    return y
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }

  for (const c of comps) {
    const cref = `component:${c.name}`
    const comp = nodeId.get(cref)!
    const anchor = compPos.get(cref)!
    for (const use of c.ports ?? []) {
      const port = portMeta.get(use.port)
      const isInput = use.direction === 'in'
      const extId = `ext:${use.port}`
      const data: ExtNodeData = {
        name: port?.externalSystem ? refName(port.externalSystem) : use.port,
        type: 'port',
        direction: isInput ? 'input' : undefined,
        port: use.port,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, railX, railY(anchor.y))
        edges.push({
          id: `e:port:${c.name}:${use.port}`,
          source: comp,
          sourceHandle: 'ext',
          target: extId,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
    }
  }

  return { nodes, edges, ghosts }
}

function GroupNode({ data }: NodeProps) {
  const { title, count } = data as GroupNodeData
  return (
    <div className="rf-group">
      <div className="rf-group-title">
        <span>{title}</span>
        <span className="count">{count}</span>
      </div>
    </div>
  )
}

function IntegrationNode({ data }: NodeProps) {
  const { name, template, dataFlow, selected, trigger, ghost, seed } = data as IntNodeData
  const onSeed = useContext(SeedContext)
  const Icon = dataFlow ? DATA_FLOW_ICONS[dataFlow] : MemoryIcon
  return (
    <div className={`rf-int${selected ? ' selected' : ''}${ghost ? ' ghost' : ''}`}>
      <div className="rf-int-head">
        <Icon className="rf-int-icon" aria-hidden />
        <span className="rf-int-name">{name}</span>
        {template && <span className="rf-int-tag">{template}</span>}
        {trigger && (
          <span className="rf-int-tag" title="schedule trigger">
            {trigger}
          </span>
        )}
        {ghost && (
          <span
            className="rf-int-tag ghost-tag"
            title="scaffolded, not in the declared topology yet"
          >
            scaffolded
          </span>
        )}
        {/* The seed action sits last: the first tag's auto margin pushes the
            whole trailing cluster right, and the button hangs off its end. */}
        {seed === 'ready' && (
          <button
            type="button"
            className="rf-int-seed nodrag"
            title="Seed a test file into this extractor's dev folder"
            onClick={(e) => {
              // The card click selects the integration; the action is not a
              // selection.
              e.stopPropagation()
              onSeed(name)
            }}
          >
            <FileUploadIcon aria-hidden />
          </button>
        )}
        {seed === 'ghost' && (
          <button
            type="button"
            className="rf-int-seed"
            disabled
            title="Seeding needs the declared topology — update the host and refresh first"
          >
            <FileUploadIcon aria-hidden />
          </button>
        )}
      </div>

      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="source" position={Position.Bottom} id="infra" />
      <Handle type="source" position={Position.Right} id="ext" />
    </div>
  )
}

// SlotNode is a create placeholder: one per block-kind column, low-contrast
// until hovered. Clicking it opens the create drawer for that kind. It has no
// handles — a slot carries no wiring.
const SLOT_LABELS: Record<SlotKind, string> = {
  extractor: 'Extractor',
  transactional: 'Core block',
  loader: 'Loader',
}

function SlotNode({ data }: NodeProps) {
  const { kind } = data as SlotNodeData
  return (
    <div className="rf-slot">
      <span className="rf-slot-plus" aria-hidden>
        +
      </span>
      <div className="rf-slot-text">
        <span className="rf-slot-name">{SLOT_LABELS[kind]}</span>
        <span className="rf-slot-hint">scaffold a new block</span>
      </div>
    </div>
  )
}

// TopicNode is a declared pub/sub topic: the first-class hop between
// components a declared topology makes visible. Contract topics show their
// contract ref; internal ones their data entity. The node draws as a
// horizontal cylinder — the message-channel glyph — so a topic reads as
// infrastructure between components, never as another component card.
function TopicNode({ data }: NodeProps) {
  const { name, entity, contract } = data as TopicNodeData
  // Topic names share a long common prefix, so lead with the short entity and
  // keep the full topic/contract in a tooltip. Fall back to the name when a
  // topic declares no entity.
  const primary = entity ?? name
  const secondary = contract ?? name
  const tip = contract ? `${name}\n${contract}` : name
  return (
    <div className="rf-infra pubsub rf-topic-cyl" title={tip}>
      {/* Silhouette: a rectangle with both ends bulging as elliptical arcs;
          the extra arc is the near cap's seam, making the left end read as
          the visible face of the cylinder. */}
      <svg className="rf-cyl" viewBox="0 0 200 76" aria-hidden focusable="false">
        <path className="rf-cyl-body" d="M 12 3 H 188 A 9 35 0 0 1 188 73 H 12 A 9 35 0 0 1 12 3 Z" />
        <path className="rf-cyl-seam" d="M 12 3 A 9 35 0 0 1 12 73" />
      </svg>
      <Handle type="target" position={Position.Left} id="in" />
      <HubIcon className="rf-infra-icon" aria-hidden />
      <div className="rf-infra-text">
        <span className="rf-infra-name">{primary}</span>
        <span className="rf-infra-kind">{secondary}</span>
      </div>
      <Handle type="source" position={Position.Right} id="out" />
    </div>
  )
}

function ExternalNode({ data }: NodeProps) {
  const { name, type, direction } = data as ExtNodeData
  const isDisk = /localstorage|localfile|disk|file/i.test(type)
  const Icon = isDisk ? HardDriveIcon : CloudIcon
  const kind = direction === 'input' ? 'source' : isDisk ? 'disk' : 'external'
  return (
    <div className="rf-ext">
      <Handle type="target" position={Position.Left} id="in" />
      <Handle type="target" position={Position.Top} id="top" />
      <Handle type="source" position={Position.Right} id="out" />
      <Icon className="rf-ext-icon" aria-hidden />
      <div className="rf-ext-text">
        <span className="rf-ext-name">{name}</span>
        <span className="rf-ext-kind" title={type}>
          {kind}
        </span>
      </div>
    </div>
  )
}

const NODE_TYPES = {
  group: GroupNode,
  integration: IntegrationNode,
  external: ExternalNode,
  topic: TopicNode,
  slot: SlotNode,
}

package template

import (
	"fmt"
	"path/filepath"
)

// The wiring vocabulary: the parameter names block templates record in
// their scaffold values and later commands (sys create/update, deploy,
// prompt suggestions) read back. They are CLI-owned convention, not
// manifest schema — a template that names its parameters otherwise simply
// gets no assembly or suggestions. One home so a vocabulary change has
// one diff, not a scavenger hunt.
const (
	KeyAppID        = "appId"
	KeyTopic        = "topic"
	KeyContract     = "contract"
	KeyPubsub       = "pubsub"
	KeyPort         = "port"
	KeyFromPort     = "fromPort"
	KeyToPort       = "toPort"
	KeyName         = "name"
	KeyOrganization = "organization"
	KeyProjectName  = "projectName"
	KeySystemClass  = "systemClass"

	// The message wiring blocks. The flat topic/contract/pubsub keys above
	// are superseded by these: a scaffold carries either a subscribe block
	// (what the component consumes, from the registry or a producing
	// sibling) or a publishes block (what it declares). Both shapes are
	// read everywhere; writers emit only the blocks.
	KeySubscribe     = "subscribe"
	KeyPublishes     = "publishes"
	KeyMessage       = "message"
	KeyDataschema    = "dataschema"
	KeyDataschemaURL = "dataschemaurl"

	// DefaultPubsub is the pub/sub component a record belongs to when it
	// predates the pubsub value being recorded.
	DefaultPubsub = "pubsub"
)

// RecordValue reads key from a scaffold record's values as a non-empty
// string. Missing, mistyped, and empty values are errors naming the
// record, so the user knows which project to fix. It is the strict
// regime: callers validating a workspace (system assembly) use it;
// callers offering suggestions use SoftValue instead.
func RecordValue(e ScaffoldEntry, key string) (string, error) {
	record := filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
	v, ok := e.Values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", record, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", record, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", record, key)
	}
	return s, nil
}

// RecordValueDefault is RecordValue with a fallback for records that
// predate the value being recorded. Only a missing key falls back; a
// present but mistyped or empty value is still an error — a record that
// names the key must say something meaningful.
func RecordValueDefault(e ScaffoldEntry, key, fallback string) (string, error) {
	if _, ok := e.Values[key]; !ok {
		return fallback, nil
	}
	return RecordValue(e, key)
}

// SoftValue reads key from a values map as a non-empty string, reporting
// false for missing, mistyped, or empty values. It is the lenient regime:
// suggestion aids and best-effort joins skip such records rather than
// failing an operation the records themselves would still allow.
func SoftValue(values map[string]any, key string) (string, bool) {
	s, ok := values[key].(string)
	if !ok || s == "" {
		return "", false
	}
	return s, true
}

// The message wiring blocks. A subscribe block names the message the
// component consumes; without pubsub/topic it is an internal subscription
// whose channel assembly resolves from the producing component. With the
// snapshot fields it is an external subscription — the registry is never
// contacted again for it.
//
// A publishes block declares what its component produces; internal and
// registry-resolved publications differ only in which fields they carry,
// and PublishesBlock's doc comment owns that split.
type SubscribeBlock struct {
	Message       string
	Pubsub        string
	Topic         string
	Dataschema    string
	DataschemaURL string
}

// PublishesBlock is a producer's message declaration. A registry-resolved
// publish carries the full channel snapshot (pubsub, topic) and the schema
// pin; a producer-declared internal publish carries only the message.
// Contract is the .NET shared-project type name, carried during the
// transition while host templates render Topics.cs from it; it is not the
// CloudEvents type.
// Contract is the .NET shared-project type name, carried during the
// transition while host templates render Topics.cs from it; it is not the
// CloudEvents type.
type PublishesBlock struct {
	Message       string
	Contract      string
	Dataschema    string
	DataschemaURL string
	Pubsub        string
	Topic         string
}

// External reports whether the declaration carries its own channel
// snapshot. External publications assemble their channel from the record
// alone; internal publications default to the system pubsub on a topic
// named after the message.
func (b *PublishesBlock) External() bool { return b.Topic != "" }

// External reports whether the subscription carries its own channel
// snapshot. External subscriptions assemble without a producer and without
// touching the registry.
func (b *SubscribeBlock) External() bool { return b.Topic != "" }

// HasSubscribeValue reports whether values carry a subscribe block. Block
// presence wins over the legacy flat keys wherever both appear — the dual
// read is a fallback, never a merge.
func HasSubscribeValue(values map[string]any) bool {
	_, ok := values[KeySubscribe]
	return ok
}

// HasPublishesValue reports whether values carry a publishes block.
func HasPublishesValue(values map[string]any) bool {
	_, ok := values[KeyPublishes]
	return ok
}

// HasMessageBlocks reports whether values use the block wiring shape at
// all. Assembly and facts treat such records as block-shaped and ignore
// their legacy flat keys.
func HasMessageBlocks(values map[string]any) bool {
	return HasSubscribeValue(values) || HasPublishesValue(values)
}

// blockMap reads one block value as the map the writers produce. The
// strict regime applies: a present block must be an object, so a mistyped
// block is an error naming the record and the block, never a silent skip.
func blockMap(e ScaffoldEntry, block string) (map[string]any, error) {
	v, ok := e.Values[block]
	if !ok {
		return nil, nil // absent is not an error; the caller decides
	}
	m, ok := v.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("%s: values.%s has type %T, expected object", recordPath(e), block, v)
	}
	return m, nil
}

// blockString reads a strict non-empty string field out of a block: mistyped
// or empty names the record and the full key path.
func blockString(e ScaffoldEntry, block, key string) (string, error) {
	m, err := blockMap(e, block)
	if err != nil {
		return "", err
	}
	v, ok := m[key]
	if !ok {
		return "", nil
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s.%s has type %T, expected string", recordPath(e), block, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s.%s is empty", recordPath(e), block, key)
	}
	return s, nil
}

// recordPath names the record in error messages, matching RecordValue.
func recordPath(e ScaffoldEntry) string {
	return filepath.Join(e.Path, filepath.FromSlash(ScaffoldRelPath))
}

// ReadSubscribeBlock strictly reads the subscribe block. The message name
// is required; the snapshot fields are each required to be non-empty
// strings when present. A record with the block and empty message is a
// broken record, not a wireless one.
func ReadSubscribeBlock(e ScaffoldEntry) (*SubscribeBlock, error) {
	if !HasSubscribeValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeySubscribe, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeySubscribe, KeyMessage)
	}
	b := &SubscribeBlock{Message: message}
	for _, f := range []struct {
		key string
		dst *string
	}{
		{KeyPubsub, &b.Pubsub},
		{KeyTopic, &b.Topic},
		{KeyDataschema, &b.Dataschema},
		{KeyDataschemaURL, &b.DataschemaURL},
	} {
		s, err := blockString(e, KeySubscribe, f.key)
		if err != nil {
			return nil, err
		}
		*f.dst = s
	}
	return b, nil
}

// ReadPublishesBlock strictly reads the publishes block. The message name
// is required; contract, dataschema, and the channel snapshot stay optional
// for internal declarations. The pubsub/topic pair is validated by system
// assembly, not here — the block reader stays a shape reader, matching how
// the subscribe branch splits concerns.
func ReadPublishesBlock(e ScaffoldEntry) (*PublishesBlock, error) {
	if !HasPublishesValue(e.Values) {
		return nil, nil
	}
	message, err := blockString(e, KeyPublishes, KeyMessage)
	if err != nil {
		return nil, err
	}
	if message == "" {
		return nil, fmt.Errorf("%s: values.%s.%s is missing", recordPath(e), KeyPublishes, KeyMessage)
	}
	b := &PublishesBlock{Message: message}
	for _, f := range []struct {
		key string
		dst *string
	}{
		{KeyContract, &b.Contract},
		{KeyDataschema, &b.Dataschema},
		{KeyDataschemaURL, &b.DataschemaURL},
		{KeyPubsub, &b.Pubsub},
		{KeyTopic, &b.Topic},
	} {
		s, err := blockString(e, KeyPublishes, f.key)
		if err != nil {
			return nil, err
		}
		*f.dst = s
	}
	return b, nil
}

// SubscribeBlockValue renders the block as the values-map entry writers
// emit. Writers never add the legacy flat keys alongside it.
func SubscribeBlockValue(b *SubscribeBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	if b.Pubsub != "" {
		m[KeyPubsub] = b.Pubsub
	}
	if b.Topic != "" {
		m[KeyTopic] = b.Topic
	}
	if b.Dataschema != "" {
		m[KeyDataschema] = b.Dataschema
	}
	if b.DataschemaURL != "" {
		m[KeyDataschemaURL] = b.DataschemaURL
	}
	return m
}

// PublishesBlockValue renders a publishes declaration as the values-map
// entry writers emit.
func PublishesBlockValue(b *PublishesBlock) map[string]any {
	m := map[string]any{KeyMessage: b.Message}
	for _, f := range []struct {
		key   string
		value string
	}{
		{KeyContract, b.Contract},
		{KeyDataschema, b.Dataschema},
		{KeyDataschemaURL, b.DataschemaURL},
		{KeyPubsub, b.Pubsub},
		{KeyTopic, b.Topic},
	} {
		if f.value != "" {
			m[f.key] = f.value
		}
	}
	return m
}

package dashboard

import (
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// DaprComponent is a parsed Dapr component definition surfaced to the flow
// canvas. Category is derived from Type so the frontend can place the node
// without re-parsing: "pubsub" and "state" render inside the system boundary,
// "binding" renders outside it — as a source when Direction is "input", a
// sink otherwise.
type DaprComponent struct {
	Name     string `json:"name"`     // metadata.name, e.g. "pubsub"
	Type     string `json:"type"`     // spec.type, e.g. "pubsub.in-memory"
	Category string `json:"category"` // "pubsub" | "state" | "binding" | "other"
	// Direction is the component's declared direction metadata, normalized
	// to "input", "output" or "input,output". Empty when the component does
	// not declare one (or declares something unrecognized) — consumers must
	// treat that as unknown rather than infer a direction.
	Direction string `json:"direction,omitempty"`
	File      string `json:"file"` // source filename, for reference
}

// componentYAML is the minimal shape read from a Dapr component file; every
// other field is ignored.
type componentYAML struct {
	Metadata struct {
		Name string `yaml:"name"`
	} `yaml:"metadata"`
	Spec struct {
		Type     string `yaml:"type"`
		Metadata []struct {
			Name  string `yaml:"name"`
			Value string `yaml:"value"`
		} `yaml:"metadata"`
	} `yaml:"spec"`
}

// readComponents parses every *.yaml/*.yml file directly under dir into a
// DaprComponent. It is best-effort, mirroring listNames: a missing directory
// yields nil, and an unreadable or unparseable file is skipped rather than
// failing the whole response. Results are sorted by Name for determinism.
func readComponents(dir string) []DaprComponent {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}

	var comps []DaprComponent
	for _, ent := range ents {
		if ent.IsDir() || !isYAML(ent.Name()) {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, ent.Name()))
		if err != nil {
			continue
		}
		var doc componentYAML
		if err := yaml.Unmarshal(data, &doc); err != nil {
			continue
		}
		name := doc.Metadata.Name
		if name == "" {
			name = stem(ent.Name())
		}
		comps = append(comps, DaprComponent{
			Name:      name,
			Type:      doc.Spec.Type,
			Category:  classify(doc.Spec.Type),
			Direction: direction(doc),
			File:      ent.Name(),
		})
	}

	sort.Slice(comps, func(i, j int) bool { return comps[i].Name < comps[j].Name })
	return comps
}

// classify maps a Dapr spec.type to the coarse category the flow canvas groups
// by: the segment before the first "." ("pubsub.in-memory" -> "pubsub"). An
// empty or dot-less type falls back to "other".
func classify(specType string) string {
	prefix, _, ok := strings.Cut(specType, ".")
	if !ok || prefix == "" {
		return "other"
	}
	switch prefix {
	case "pubsub", "state", "bindings":
		if prefix == "bindings" {
			return "binding"
		}
		return prefix
	default:
		return "other"
	}
}

// direction returns the component's "direction" spec.metadata entry
// normalized to "input", "output" or "input,output" (Dapr accepts a comma
// list in either order, with arbitrary spacing and casing). An absent entry
// or any unrecognized value yields "" — unknown is surfaced, not guessed.
func direction(doc componentYAML) string {
	for _, m := range doc.Spec.Metadata {
		if m.Name == "direction" {
			return normalizeDirection(m.Value)
		}
	}
	return ""
}

func normalizeDirection(raw string) string {
	if raw == "" {
		return ""
	}
	var in, out bool
	for tok := range strings.SplitSeq(raw, ",") {
		switch strings.ToLower(strings.TrimSpace(tok)) {
		case "input":
			in = true
		case "output":
			out = true
		default:
			return ""
		}
	}
	switch {
	case in && out:
		return "input,output"
	case in:
		return "input"
	default:
		return "output"
	}
}

func isYAML(name string) bool {
	return strings.HasSuffix(name, ".yaml") || strings.HasSuffix(name, ".yml")
}

// stem returns a filename without its extension.
func stem(name string) string {
	return strings.TrimSuffix(name, filepath.Ext(name))
}
