package dashboard

import "github.com/integrio-intropy/intropy-cli/internal/template"

// messageWiring is the message a component declares, read from its scaffold
// record: the one message it publishes or subscribes to, plus the channel
// snapshot and schema pin a registry-resolved declaration recorded.
//
// Only a record using the message blocks reports one. A legacy flat-key
// record declares a topic and a contract, not a message — the flow canvas
// already draws those as the topic they are, and minting a message name out
// of the topic would show a declaration the record never made.
type messageWiring struct {
	// Direction is template.MessageDirectionPublish or …Subscribe: which
	// half of the message a component declares.
	Direction string `json:"direction"`

	// Message is the message name — the CloudEvents type for an internal
	// declaration, the registry's message name for a resolved one.
	Message string `json:"message"`

	// Contract is the .NET shared-project type recorded beside a
	// publication, transitional while host templates render Topics.cs from
	// it. A subscribe block never carries one.
	Contract string `json:"contract,omitempty"`

	// Dataschema and DataschemaURL are the registry schema a resolved
	// declaration pinned: the logical xid and the versioned URL it came
	// from. An internal declaration has neither.
	Dataschema    string `json:"dataschema,omitempty"`
	DataschemaURL string `json:"dataschemaUrl,omitempty"`

	// Pubsub and Topic are the channel snapshot a resolved declaration
	// carries. An internal declaration has none: assembly derives the
	// channel from the producing sibling, or from the system default.
	Pubsub string `json:"pubsub,omitempty"`
	Topic  string `json:"topic,omitempty"`

	// External marks a declaration that carries its own channel snapshot,
	// so it assembles without a producer in this system.
	External bool `json:"external,omitempty"`
}

// readMessageWiring derives a record's declared message wiring. It is the
// lenient regime a read surface owes the whole workspace: a record that
// misshapes a block, or contradicts itself by declaring both directions,
// reports no wiring rather than failing the response that carries every
// other integration. `sys create` is the surface that reports those.
func readMessageWiring(e template.ScaffoldEntry) *messageWiring {
	if !template.HasMessageBlocks(e.Values) {
		return nil
	}
	pub, pubErr := template.ReadPublishesBlock(e)
	sub, subErr := template.ReadSubscribeBlock(e)
	if pubErr != nil || subErr != nil || (pub != nil && sub != nil) {
		return nil
	}
	switch {
	case pub != nil:
		return &messageWiring{
			Direction:     template.MessageDirectionPublish,
			Message:       pub.Message,
			Contract:      pub.Contract,
			Dataschema:    pub.Dataschema,
			DataschemaURL: pub.DataschemaURL,
			Pubsub:        pub.Pubsub,
			Topic:         pub.Topic,
			External:      pub.External(),
		}
	case sub != nil:
		return &messageWiring{
			Direction:     template.MessageDirectionSubscribe,
			Message:       sub.Message,
			Dataschema:    sub.Dataschema,
			DataschemaURL: sub.DataschemaURL,
			Pubsub:        sub.Pubsub,
			Topic:         sub.Topic,
			External:      sub.External(),
		}
	}
	return nil
}

