package dashboard

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

func entryWith(values map[string]any) template.ScaffoldEntry {
	return template.ScaffoldEntry{Scaffold: template.Scaffold{Values: values}}
}

func TestReadMessageWiringPublishes(t *testing.T) {
	got := readMessageWiring(entryWith(map[string]any{
		"appId": "product-extractor",
		"publishes": map[string]any{
			"message":  "io.intropy.acme.product.export",
			"contract": "RawProduct",
		},
	}))
	if got == nil {
		t.Fatal("wiring = nil, want the publishes declaration")
	}
	want := messageWiring{
		Direction: template.MessageDirectionPublish,
		Message:   "io.intropy.acme.product.export",
		Contract:  "RawProduct",
	}
	if *got != want {
		t.Errorf("wiring = %+v, want %+v", *got, want)
	}
}

// A registry-resolved subscription carries its channel snapshot and schema
// pin, and reports itself external — the flow view marks it as wiring
// without a producer in this system.
func TestReadMessageWiringExternalSubscribe(t *testing.T) {
	got := readMessageWiring(entryWith(map[string]any{
		"subscribe": map[string]any{
			"message":       "io.intropy.acme.product.export",
			"pubsub":        "product-distribution-pubsub",
			"topic":         "sbt-test-product-extractor-001",
			"dataschema":    "/schemagroups/g/schemas/product-export.v1",
			"dataschemaurl": "https://registry.example.com/versions/1",
		},
	}))
	if got == nil {
		t.Fatal("wiring = nil, want the subscribe declaration")
	}
	want := messageWiring{
		Direction:     template.MessageDirectionSubscribe,
		Message:       "io.intropy.acme.product.export",
		Dataschema:    "/schemagroups/g/schemas/product-export.v1",
		DataschemaURL: "https://registry.example.com/versions/1",
		Pubsub:        "product-distribution-pubsub",
		Topic:         "sbt-test-product-extractor-001",
		External:      true,
	}
	if *got != want {
		t.Errorf("wiring = %+v, want %+v", *got, want)
	}
}

// The read regime is lenient where assembly is strict: a legacy flat-key
// record declares no message, a record that contradicts itself declares
// nothing readable, and a misshapen block reports absence rather than
// failing the response that carries every other integration.
func TestReadMessageWiringAbsent(t *testing.T) {
	for name, values := range map[string]map[string]any{
		"legacy flat keys": {"topic": "product-export", "contract": "RawProduct"},
		"both directions": {
			"publishes": map[string]any{"message": "a"},
			"subscribe": map[string]any{"message": "a"},
		},
		"block is not an object": {"subscribe": "io.intropy.acme.product.export"},
		"block without a message": {
			"publishes": map[string]any{"contract": "RawProduct"},
		},
	} {
		if got := readMessageWiring(entryWith(values)); got != nil {
			t.Errorf("%s: wiring = %+v, want nil", name, got)
		}
	}
}

// The flow payload carries the declaration, so the canvas can show it on a
// ghost card before `sys create` folds it into the host.
func TestFlowCarriesMessageWiring(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	proj := filepath.Join(tmp, "sales", "product-loader")
	if err := os.MkdirAll(filepath.Join(proj, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	record := `{"schemaVersion":1,"template":"loader","owner":"integrio-intropy",` +
		`"repo":"intropy-templates","version":"v0.1.0","blockKind":"loader","dataFlow":"out",` +
		`"values":{"appId":"product-loader","subscribe":{"message":"io.intropy.acme.product.export",` +
		`"pubsub":"product-distribution-pubsub","topic":"sbt-test-001",` +
		`"dataschema":"/schemagroups/g/schemas/product-export.v1"}}}` + "\n"
	if err := os.WriteFile(filepath.Join(proj, ".intropy", "scaffold.json"), []byte(record), 0o644); err != nil {
		t.Fatal(err)
	}

	rec := get(t, testHandler(t, "."), "/api/flow")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	var nodes []struct {
		Name    string         `json:"name"`
		Message *messageWiring `json:"message"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &nodes); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(nodes) != 1 {
		t.Fatalf("nodes = %d, want 1", len(nodes))
	}
	m := nodes[0].Message
	if m == nil {
		t.Fatal("message = nil, want the subscribe declaration")
	}
	if m.Direction != template.MessageDirectionSubscribe || m.Message != "io.intropy.acme.product.export" || !m.External {
		t.Errorf("message = %+v, want an external subscribe on the product export", *m)
	}
}

