// The counterparty round-trips: a subscription records who produces the
// message and under which group, a publication records only the group —
// its producer is the component the record belongs to.
func TestCounterpartyRoundTrip(t *testing.T) {
	sub := &SubscribeBlock{
		Message:  "io.intropy.acme.product.export",
		Pubsub:   "product-distribution-pubsub",
		Topic:    "sbt-product-export-001",
		Producer: "perfion-extractor",
		Group:    "io.intropy.acme.product",
	}
	got, err := ReadSubscribeBlock(ScaffoldEntry{
		Scaffold: Scaffold{Values: map[string]any{KeySubscribe: SubscribeBlockValue(sub)}},
	})
	if err != nil {
		t.Fatalf("ReadSubscribeBlock: %v", err)
	}
	if *got != *sub {
		t.Errorf("subscribe block = %+v, want %+v", *got, *sub)
	}

	pub := &PublishesBlock{
		Message: "io.intropy.acme.product.export",
		Group:   "io.intropy.acme.product",
	}
	gotPub, err := ReadPublishesBlock(ScaffoldEntry{
		Scaffold: Scaffold{Values: map[string]any{KeyPublishes: PublishesBlockValue(pub)}},
	})
	if err != nil {
		t.Fatalf("ReadPublishesBlock: %v", err)
	}
	if *gotPub != *pub {
		t.Errorf("publishes block = %+v, want %+v", *gotPub, *pub)
	}
}

// A record written before the counterparty was recorded reads as it always
