// Package message is the message discovery surface behind `intropy message
// list` and `message show`: every message the read-only xRegistry serves,
// merged with the messages a workspace's scaffold records declare through
// publishes blocks.
//
// It owns the whole capability — config resolution, the registry read, the
// workspace scan, the merge order, and both output formats — so the cobra
// commands are flag shims and every other consumer (the dashboard) calls
// the same entry points and serves what they print. A second implementation
// would have to get the refusals right again: an unconfigured registry, an
// ambiguous reference, a message whose group carries no definition.
//
// It never writes anything. Resolving a message into scaffold wiring is
// `int create --subscribe`, not this package.
package message

import (
	"fmt"
	"io"
	"os"
	"sort"

	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// Output formats callers select with OutputFormat, matching the
// --output values and internal/deploy's vocabulary.
const (
	OutputPlain = "plain"
	OutputJSON  = "json"
)

// Where an entry came from. A registry message is external and carries its
// producing channels and schema pin; a workspace message is internal, read
// from a publishes block in a scaffold record.
const (
	SourceRegistry  = "registry"
	SourceWorkspace = "workspace"
)

// Entry is one message as the message surface emits it. One shape for
// registry-served and workspace-declared messages, so the human table, the
// JSON document, and the show detail cannot drift apart.
type Entry struct {
	Message string `json:"message"`
	Source  string `json:"source"`

	Group          string              `json:"group,omitempty"`
	Type           string              `json:"type,omitempty"`
	Envelope       string              `json:"envelope,omitempty"`
	Channels       []string            `json:"channels,omitempty"` // <pubsub>/<topic>
	DataSchema     string              `json:"dataschema,omitempty"`
	DataSchemaURL  string              `json:"dataschemaurl,omitempty"`
	DataSchemaName string              `json:"dataschemaname,omitempty"`
	Contract       string              `json:"contract,omitempty"`
	Path           string              `json:"path,omitempty"` // workspace: the record's project directory
	EnvelopeMeta   []EnvelopeAttribute `json:"envelopeMetadata,omitempty"`
}

// EnvelopeAttribute is one envelope metadata attribute: its name, its
// value, and whether the envelope requires it.
type EnvelopeAttribute struct {
	Name     string `json:"name"`
	Value    string `json:"value,omitempty"`
	Required bool   `json:"required,omitempty"`
}

// stream is the output half every option struct carries, mirroring how
// internal/deploy projects its options onto one writer pair.
type stream struct {
	Format string
	Stdout io.Writer
	Stderr io.Writer
}

func (s *stream) applyDefaults() {
	if s.Format == "" {
		s.Format = OutputPlain
	}
	if s.Stdout == nil {
		s.Stdout = os.Stdout
	}
	if s.Stderr == nil {
		s.Stderr = os.Stderr
	}
}

// warnf writes one non-fatal diagnostic. Warnings never share stdout: a
// caller decoding the JSON document must not have to skip them.
func (s stream) warnf(err error) {
	fmt.Fprintln(s.Stderr, "warning:", err)
}

// resolveClient builds the registry client, layering the caller's
// RegistryURL override over the config the same way internal/deploy layers
// --gitops-repo. An unconfigured registry is config's own error, naming
// every way to set it — there is no guessed default.
func resolveClient(registryURL, userAgent string) (*xregistry.Client, error) {
	cfg, err := config.Load()
	if err != nil {
		return nil, err
	}
	url, err := cfg.Resolve(config.Flags{RegistryURL: registryURL}).RequireRegistryURL()
	if err != nil {
		return nil, err
	}
	if userAgent == "" {
		userAgent = "intropy-cli"
	}
	return xregistry.New(url, xregistry.WithUserAgent(userAgent))
}

// sortEntries orders a merged list: registry messages by ref, then
// workspace messages by name — the stable order both table and JSON echo.
func sortEntries(entries []Entry) {
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Source != entries[j].Source {
			return entries[i].Source == SourceRegistry
		}
		return entries[i].Message < entries[j].Message
	})
}

package message

// The workspace half: the messages a workspace declares itself, read from
// the publishes blocks of the scaffold records under a directory. No
// network, and no dependency on the registry being configured — a
// workspace's own messages are answerable offline.

import (
	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// workspaceEntries indexes the publishes declarations under dir. Scan and
// parse warnings are non-fatal: a malformed sibling record must not hide
// the messages the rest of the workspace declares.
func workspaceEntries(dir string, warnf func(error)) []Entry {
	entries, warnings := template.ListScaffolds(dir)
	for _, w := range warnings {
		warnf(w)
	}
	seen := map[string]bool{}
	var out []Entry
	for _, e := range entries {
		pub, err := template.ReadPublishesBlock(e)
		if err != nil || pub == nil {
			// Malformed block: skipped here — listing must show what is
			// resolvable; assembly is the surface that reports the record.
			continue
		}
		if seen[pub.Message] {
			continue
		}
		seen[pub.Message] = true
		out = append(out, Entry{
			Message:    pub.Message,
			Source:     SourceWorkspace,
			Type:       pub.Message,
			Group:      pub.Group,
			DataSchema: pub.Dataschema,
			Contract:   pub.Contract,
			Path:       e.Path,
		})
	}
	sortEntries(out)
	return out
}

package message

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"text/tabwriter"
)

// ListOptions selects what List reports and where it writes.
type ListOptions struct {
	// Dir is the workspace scanned for publishes declarations; empty means
	// the current directory. It is not validated here — a directory that
	// does not exist simply declares no messages, and rejecting a bad path
	// is the caller's input validation.
	Dir string

	// Group narrows the result to one registry message group. Workspace
	// messages carry no group, so a group filter excludes them entirely
	// rather than showing an arbitrary subset.
	Group string

	// RegistryURL overrides the configured xRegistry base URL. Empty
	// resolves through the config, the same precedence every other setting
	// uses; an unconfigured registry is an error, never a guessed default.
	RegistryURL string

	// OutputFormat is OutputPlain or OutputJSON. Empty means OutputPlain.
	OutputFormat string

	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
}

func (o ListOptions) stream() stream {
	return stream{Format: o.OutputFormat, Stdout: o.Stdout, Stderr: o.Stderr}
}

// List reports every message the registry serves, merged with the ones this
// workspace declares, and writes them as a table or a JSON document.
//
// The registry read is required: listing exists to answer "what can I
// subscribe to", and silently reporting only the workspace's own messages
// would answer a different question. The workspace scan, by contrast, is
// best-effort — a malformed record warns and is skipped.
func List(ctx context.Context, opts ListOptions) error {
	out := opts.stream()
	out.applyDefaults()

	dir := opts.Dir
	if dir == "" {
		dir = "."
	}

	var entries []Entry
	if opts.Group == "" {
		entries = append(entries, workspaceEntries(dir, out.warnf)...)
	}

	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return err
	}
	registry, err := registryEntries(ctx, client, opts.Group)
	if err != nil {
		return err
	}
	entries = append(entries, registry...)

	if out.Format == OutputJSON {
		return writeEntriesJSON(out, entries)
	}
	return writeEntriesTable(out, entries)
}

// writeEntriesJSON emits the document. An empty result is an empty array,
// never null: a consumer decoding it should not have to nil-check.
func writeEntriesJSON(out stream, entries []Entry) error {
	if entries == nil {
		entries = []Entry{}
	}
	enc := json.NewEncoder(out.Stdout)
	enc.SetIndent("", "  ")
	return enc.Encode(entries)
}

func writeEntriesTable(out stream, entries []Entry) error {
	if len(entries) == 0 {
		fmt.Fprintln(out.Stderr, "no messages found")
		return nil
	}
	tw := tabwriter.NewWriter(out.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "MESSAGE\tSOURCE\tGROUP\tCHANNEL\tSCHEMA")
	for _, e := range entries {
		channel := strings.Join(e.Channels, ", ")
		if channel == "" {
			channel = "-"
		}
		schema := e.DataSchemaName
		if schema == "" {
			schema = "-"
		}
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\n", e.Message, e.Source, e.Group, channel, schema)
	}
	return tw.Flush()
}

package message

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// ShowOptions selects which message Show prints and where it writes.
type ShowOptions struct {
	// Ref is the message reference: a bare message id, or a full
	// /messagegroups/<gid>/messages/<mid> xid.
	Ref string

	// Dir is the workspace searched before the registry; empty means the
	// current directory.
	Dir string

	// RegistryURL overrides the configured xRegistry base URL, as on
	// ListOptions.
	RegistryURL string

	// OutputFormat is OutputPlain or OutputJSON. Empty means OutputPlain.
	OutputFormat string

	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
}

func (o ShowOptions) stream() stream {
	return stream{Format: o.OutputFormat, Stdout: o.Stdout, Stderr: o.Stderr}
}

// Show prints one message's definition: its envelope metadata, its
// producing channels, and its schema pin.
//
// The workspace is searched first. A local publish answers without the
// network and without the registry being configured, and a name both sides
// declare is shown with its local source — the workspace is the authority
// on what it produces.
func Show(ctx context.Context, opts ShowOptions) error {
	out := opts.stream()
	out.applyDefaults()

	dir := opts.Dir
	if dir == "" {
		dir = "."
	}

	// Warnings are collected rather than written as they are found: the
	// workspace scan runs before the answer is known, and a scan warning
	// must not precede a JSON document on the wrong stream ordering.
	var warnings []error
	local := workspaceEntries(dir, func(w error) { warnings = append(warnings, w) })
	for _, w := range warnings {
		out.warnf(w)
	}
	for i := range local {
		if local[i].Message == opts.Ref {
			return writeEntry(out, &local[i])
		}
	}

	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return err
	}
	e, err := registryEntry(ctx, client, opts.Ref)
	if err != nil {
		return err
	}
	return writeEntry(out, e)
}

// writeEntry writes one message: human rows to stdout, or the JSON
// document. Diagnostics never share the stdout stream.
func writeEntry(out stream, e *Entry) error {
	if out.Format == OutputJSON {
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		return enc.Encode(e)
	}

	fmt.Fprintf(out.Stdout, "message:   %s\n", e.Message)
	fmt.Fprintf(out.Stdout, "source:    %s\n", e.Source)
	if e.Type != "" && e.Type != e.Message {
		fmt.Fprintf(out.Stdout, "type:      %s\n", e.Type)
	}
	if e.Envelope != "" {
		fmt.Fprintf(out.Stdout, "envelope:  %s\n", e.Envelope)
	}
	if e.Group != "" {
		fmt.Fprintf(out.Stdout, "group:     %s\n", e.Group)
	}
	if e.Path != "" {
		fmt.Fprintf(out.Stdout, "path:      %s\n", e.Path)
	}
	if e.Contract != "" {
		fmt.Fprintf(out.Stdout, "contract:  %s\n", e.Contract)
	}
	if len(e.Channels) > 0 {
		fmt.Fprintf(out.Stdout, "channels:  %s\n", strings.Join(e.Channels, ", "))
	}
	if e.DataSchema != "" {
		fmt.Fprintf(out.Stdout, "dataschema: %s\n", e.DataSchema)
	}
	if e.DataSchemaURL != "" {
		fmt.Fprintf(out.Stdout, "dataschemaurl: %s\n", e.DataSchemaURL)
	}
	for _, kv := range e.EnvelopeMeta {
		required := ""
		if kv.Required {
			required = " (required)"
		}
		value := "-"
		if kv.Value != "" {
			value = kv.Value
		}
		fmt.Fprintf(out.Stdout, "envelope %s: %s%s\n", kv.Name, value, required)
	}
	return nil
}

