// writePublisher writes a scaffold record declaring one published message,
// the shape workspace entries are read from.
func writePublisher(t *testing.T, dir, appID, msg string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(dir, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	record := fmt.Sprintf(`{"schemaVersion":1,"template":"extractor","owner":"integrio-intropy",`+
		`"repo":"intropy-templates","version":"v0.4.0","blockKind":"extractor","dataFlow":"in",`+
		`"values":{"appId":%q,"publishes":{"message":%q,"contract":"RawOrder"}}}`+"\n", appID, msg)
	if err := os.WriteFile(filepath.Join(dir, ".intropy", "scaffold.json"), []byte(record), 0o644); err != nil {
		t.Fatal(err)
	}
}

// The JSON document is the dashboard's contract: it decodes into Entry and
// carries the registry's channel and schema pin alongside the workspace's
// own declarations.
func TestListJSONMergesRegistryAndWorkspace(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryFixture(t))
	dir := t.TempDir()
	writePublisher(t, filepath.Join(dir, "order-extractor"), "order-extractor", "io.intropy.acme.order.created")

	var stdout, stderr bytes.Buffer
	err := List(context.Background(), ListOptions{
		Dir:          dir,
		OutputFormat: OutputJSON,
		Stdout:       &stdout,
		Stderr:       &stderr,
	})
	if err != nil {
		t.Fatalf("List: %v", err)
	}

	var entries []Entry
	if err := json.Unmarshal(stdout.Bytes(), &entries); err != nil {
		t.Fatalf("output is not JSON: %v\n%s", err, stdout.String())
	}
	if len(entries) != 2 {
		t.Fatalf("entries = %d, want 2: %+v", len(entries), entries)
	}
	// Registry entries sort ahead of workspace ones.
	reg, ws := entries[0], entries[1]
	if reg.Source != SourceRegistry || reg.Message != "io.intropy.acme.product.export" {
		t.Errorf("first entry = %+v, want the registry's product export", reg)
	}
	if reg.Group != "io.intropy.acme.product" {
		t.Errorf("group = %q, want io.intropy.acme.product", reg.Group)
	}
	if len(reg.Channels) != 1 || reg.Channels[0] != "product-distribution-pubsub/sbt-product-export-001" {
		t.Errorf("channels = %v, want the producer endpoint's channel", reg.Channels)
	}
	if !strings.HasSuffix(reg.DataSchemaURL, "/product-export.v1/versions/1") {
		t.Errorf("dataschemaurl = %q, want the default version pinned", reg.DataSchemaURL)
	}
