package message

// The wiring half: turn a message reference into the block a scaffold
// record carries. Read-only against the registry — writing the record is
// template.Create's job, and this package never renders anything.
//
// Both directions resolve once. The registry serves no per-entity lookups,
// so a resolution is one GET /export and every join happens in memory;
// re-resolving to answer a follow-up question would re-fetch the whole
// document.

import (
	"context"
	"errors"
	"fmt"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// PickChannel resolves the one choice resolution cannot make for itself:
// which producing channel to subscribe on when a message has several. It
// declines by returning the ambiguity error it was given.
//
// A nil picker makes ambiguity an error listing every candidate, which is
// what a non-interactive caller wants — a server answers the request with
// the candidates rather than picking on the user's behalf. The CLI passes a
// prompt. Presentation stays with the caller; the choice stays here.
type PickChannel func(*xregistry.AmbiguousProducerError) (xregistry.Channel, error)

// SubscribeOptions selects the message a consuming component subscribes to.
type SubscribeOptions struct {
	// Ref is the message reference: a bare message id, or a full
	// /messagegroups/<gid>/messages/<mid> xid.
	Ref string

	// RegistryURL overrides the configured xRegistry base URL, as on
	// ListOptions.
	RegistryURL string

	UserAgent string

	// PickChannel chooses among several producing channels. Nil makes an
	// ambiguous message an error carrying the candidates.
	PickChannel PickChannel
}

// PublishesOptions selects the message a producing component declares.
type PublishesOptions struct {
	Ref         string
	RegistryURL string
	UserAgent   string
}

// RefsOptions selects the candidate pool offered as prompt suggestions.
type RefsOptions struct {
	RegistryURL string
	UserAgent   string
}

// Subscribe resolves a message reference into the subscribe block a
// consuming component's scaffold record carries: the message, the channel
// its producer publishes on, the schema pinned to its default version, and
// the counterparty the subscribing workspace could not otherwise learn.
//
// Every failure here is hard. A caller naming a message asked for this
// wiring; falling back to an unwired record would leave a component
// listening to nothing.
func Subscribe(ctx context.Context, opts SubscribeOptions) (*template.SubscribeBlock, error) {
	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return nil, err
	}
	res, err := client.Resolve(ctx, opts.Ref)
	if err != nil {
		return nil, err
	}
	channel, err := subscribeChannel(res, opts.PickChannel)
	if err != nil {
		return nil, err
	}
	return &template.SubscribeBlock{
		Message:       res.Message,
		Pubsub:        channel.Pubsub,
		Topic:         channel.Topic,
		Dataschema:    res.DataSchema,
		DataschemaURL: res.DataSchemaURL,
		// The counterparty, recorded once: which endpoint produces this
		// message and which group it belongs to. The subscribing workspace
		// cannot derive either, and assembly never re-asks the registry.
		Producer: channel.Endpoint,
		Group:    res.Group,
	}, nil
}

// Publishes resolves a message reference into the publishes block a
// producing component's scaffold record carries.
//
// The channel is not a choice here, unlike Subscribe: every channel on the
// message belongs to an existing producer, so picking one would make this
// component a second producer on someone else's channel. Zero producers
// can only mean the endpoint is not registered yet, and the remediation
// names that rather than a CLI fix.
func Publishes(ctx context.Context, opts PublishesOptions) (*template.PublishesBlock, error) {
	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return nil, err
	}
	res, err := client.Resolve(ctx, opts.Ref)
	if err != nil {
		return nil, err
	}
	channel, err := res.SubscribeChannel()
	if err != nil {
		var amb *xregistry.AmbiguousProducerError
		if errors.As(err, &amb) {
			return nil, fmt.Errorf("%w\na new producer cannot pick among existing channels; register the endpoint for this component in the registry first", amb)
		}
		var no *xregistry.NoProducerError
		if errors.As(err, &no) {
			return nil, fmt.Errorf("%w\nregister the producing endpoint for this component in the registry before scaffolding it", no)
		}
		return nil, err
	}
	return &template.PublishesBlock{
		Message:       res.Message,
		Pubsub:        channel.Pubsub,
		Topic:         channel.Topic,
		Dataschema:    res.DataSchema,
		DataschemaURL: res.DataSchemaURL,
		// The group, not the producer: the producing endpoint is this
		// component, so recording it would restate the record's identity.
		Group: res.Group,
	}, nil
}

// Refs lists every message reference the registry serves, for offering as
// prompt suggestions. Suggestion metadata only — a ref becomes a value
// through a confirmed prompt or an explicit resolution, never through
// being listed. A workspace's own messages join through workspace facts,
// not here.
func Refs(ctx context.Context, opts RefsOptions) ([]string, error) {
	client, err := resolveClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}
	var refs []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			refs = append(refs, id)
		}
	}
	sortRefs(refs)
	return refs, nil
}

// subscribeChannel takes the message's one producing channel, or defers the
// choice to the picker when it has several.
func subscribeChannel(res *xregistry.ResolvedMessage, pick PickChannel) (xregistry.Channel, error) {
	channel, err := res.SubscribeChannel()
	if err == nil {
		return channel, nil
	}
	var amb *xregistry.AmbiguousProducerError
	if pick == nil || !errors.As(err, &amb) {
		return xregistry.Channel{}, err
	}
	return pick(amb)
}

