package message

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// registryWithEndpoints serves the fixture export with a caller-chosen
// producer endpoint set, so the one-producer, no-producer and
// several-producer paths run against an otherwise identical registry.
func registryWithEndpoints(t *testing.T, endpointsJSON string) string {
	t.Helper()
	mux := http.NewServeMux()
	mux.HandleFunc("GET /export", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{
  "specversion": "1.0-rc2x",
  "registryid": "intropy",
  "messagegroups": {
    "io.intropy.acme.product": {
      "messagegroupid": "io.intropy.acme.product",
      "messages": {
        "io.intropy.acme.product.export": {
          "messageid": "io.intropy.acme.product.export",
          "versions": {
            "1": {
              "versionid": "1",
              "isdefault": true,
              "envelope": "CloudEvents/1.0",
              "envelopemetadata": {"type": {"value": "io.intropy.acme.product.export", "required": true}},
              "dataschemaxid": "/schemagroups/io.intropy.acme.product/schemas/product-export.v1"
            }
          }
        }
      }
    }
  },
  "endpoints": %s,
  "schemagroups": {
    "io.intropy.acme.product": {
      "schemagroupid": "io.intropy.acme.product",
      "schemas": {
        "product-export.v1": {
          "schemaid": "product-export.v1",
          "versions": {
            "1": {"versionid": "1", "isdefault": true, "xid": "/schemagroups/io.intropy.acme.product/schemas/product-export.v1/versions/1"}
          }
        }
      }
    }
  }
}`, endpointsJSON)
	})
	svc := httptest.NewServer(mux)
	t.Cleanup(svc.Close)
	return svc.URL
}

const oneProducer = `{
  "perfion-extractor": {"endpointid": "perfion-extractor", "usage": ["producer"],
    "channel": "product-distribution-pubsub/sbt-product-export-001",
    "messagegroups": ["/messagegroups/io.intropy.acme.product"]}
}`

const twoProducers = `{
  "perfion-extractor": {"endpointid": "perfion-extractor", "usage": ["producer"],
    "channel": "product-distribution-pubsub/sbt-product-export-001",
    "messagegroups": ["/messagegroups/io.intropy.acme.product"]},
  "erp-extractor": {"endpointid": "erp-extractor", "usage": ["producer"],
    "channel": "erp-distribution-pubsub/sbt-erp-export-001",
    "messagegroups": ["/messagegroups/io.intropy.acme.product"]}
}`

// The subscribe block carries the whole snapshot, counterparty included:
// the producing endpoint and the group are what a consuming workspace
// cannot derive for itself.
func TestSubscribeResolvesTheFullSnapshot(t *testing.T) {
	url := registryWithEndpoints(t, oneProducer)
	t.Setenv("INTROPY_REGISTRY_URL", url)

	block, err := Subscribe(context.Background(), SubscribeOptions{
		Ref: "io.intropy.acme.product.export",
	})
	if err != nil {
		t.Fatalf("Subscribe: %v", err)
	}
	want := "io.intropy.acme.product.export"
	if block.Message != want {
		t.Errorf("message = %q, want %q", block.Message, want)
	}
	if block.Pubsub != "product-distribution-pubsub" || block.Topic != "sbt-product-export-001" {
		t.Errorf("channel = %s/%s, want the producer endpoint's", block.Pubsub, block.Topic)
	}
	if block.Producer != "perfion-extractor" {
		t.Errorf("producer = %q, want perfion-extractor", block.Producer)
	}
	if block.Group != "io.intropy.acme.product" {
		t.Errorf("group = %q, want io.intropy.acme.product", block.Group)
	}
	if !strings.HasSuffix(block.DataschemaURL, "/product-export.v1/versions/1") {
		t.Errorf("dataschemaurl = %q, want the default version pinned", block.DataschemaURL)
	}
}

// A nil picker is the non-interactive contract: ambiguity is an error
// carrying every candidate, so a server can answer the request with them
// rather than picking on the user's behalf.
func TestSubscribeAmbiguousWithoutPickerCarriesCandidates(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, twoProducers))

	_, err := Subscribe(context.Background(), SubscribeOptions{
		Ref: "io.intropy.acme.product.export",
	})
	var amb *xregistry.AmbiguousProducerError
	if !errors.As(err, &amb) {
		t.Fatalf("err = %v, want AmbiguousProducerError", err)
	}
	if len(amb.Channels) != 2 {
		t.Fatalf("channels = %+v, want both candidates", amb.Channels)
	}
}

// A picker resolves the ambiguity in the same resolution: the registry
// serves no per-entity lookup, so asking again would re-fetch the whole
// export.
func TestSubscribeAmbiguousWithPicker(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, twoProducers))

	calls := 0
	block, err := Subscribe(context.Background(), SubscribeOptions{
		Ref: "io.intropy.acme.product.export",
		PickChannel: func(amb *xregistry.AmbiguousProducerError) (xregistry.Channel, error) {
			calls++
			for _, c := range amb.Channels {
				if c.Endpoint == "erp-extractor" {
					return c, nil
				}
			}
			return xregistry.Channel{}, amb
		},
	})
	if err != nil {
		t.Fatalf("Subscribe: %v", err)
	}
	if calls != 1 {
		t.Errorf("picker called %d times, want 1", calls)
	}
	if block.Pubsub != "erp-distribution-pubsub" || block.Producer != "erp-extractor" {
		t.Errorf("block = %+v, want the picked channel", block)
	}
}

// A picker that declines returns the ambiguity, not a half-resolved block.
func TestSubscribePickerDeclining(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, twoProducers))

	_, err := Subscribe(context.Background(), SubscribeOptions{
		Ref: "io.intropy.acme.product.export",
		PickChannel: func(amb *xregistry.AmbiguousProducerError) (xregistry.Channel, error) {
			return xregistry.Channel{}, amb
		},
	})
	var amb *xregistry.AmbiguousProducerError
	if !errors.As(err, &amb) {
		t.Fatalf("err = %v, want the ambiguity to survive", err)
	}
}

// The picker is only consulted for ambiguity: one producing channel is not
// a choice.
func TestSubscribeSingleChannelSkipsPicker(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, oneProducer))

	_, err := Subscribe(context.Background(), SubscribeOptions{
		Ref: "io.intropy.acme.product.export",
		PickChannel: func(*xregistry.AmbiguousProducerError) (xregistry.Channel, error) {
			t.Fatal("picker consulted for an unambiguous message")
			return xregistry.Channel{}, nil
		},
	})
	if err != nil {
		t.Fatalf("Subscribe: %v", err)
	}
}

// Publishes records the group but never a producer: the producing endpoint
// is the component the record belongs to.
func TestPublishesRecordsGroupNotProducer(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, oneProducer))

	block, err := Publishes(context.Background(), PublishesOptions{
		Ref: "io.intropy.acme.product.export",
	})
	if err != nil {
		t.Fatalf("Publishes: %v", err)
	}
	if block.Group != "io.intropy.acme.product" {
		t.Errorf("group = %q, want io.intropy.acme.product", block.Group)
	}
	if block.Pubsub != "product-distribution-pubsub" || block.Topic != "sbt-product-export-001" {
		t.Errorf("channel = %s/%s, want the registered channel", block.Pubsub, block.Topic)
	}
}

// A producer never picks: several channels each belong to an existing
// producer, and none is a registration for this component.
func TestPublishesRefusesToPickAChannel(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, twoProducers))

	_, err := Publishes(context.Background(), PublishesOptions{
		Ref: "io.intropy.acme.product.export",
	})
	var amb *xregistry.AmbiguousProducerError
	if !errors.As(err, &amb) {
		t.Fatalf("err = %v, want AmbiguousProducerError", err)
	}
	if !strings.Contains(err.Error(), "register the endpoint for this component") {
		t.Errorf("error %q should name the registration remediation", err)
	}
}

// No producing endpoint means the registry has not declared this component
// yet; the remediation names that rather than a CLI fix.
func TestPublishesNoProducerNamesTheRegistration(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryWithEndpoints(t, `{}`))

