package dashboard

// The registry message surface: what `intropy message list` reports, served
// as-is. Distinct from messagedocs.go, which reads the authored payload
// descriptions for a port out of the system's messages/<port>.md sidecars —
// those describe a file arriving over a port, these are message definitions
// the registry declares.

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"

	"github.com/integrio-intropy/intropy-cli/internal/message"
)

// messageProvider reports the messages available to this workspace.
//
// Like topologyProvider it never fails: an unconfigured or unreachable
// registry comes back as a diagnostic beside whatever the workspace itself
// declares, because "we could not ask" and "there are none" must not render
// the same. Which of the two it was is the command's business to say, not
// this package's to guess.
type messageProvider func(ctx context.Context) (entries []message.Entry, diagnostics []string)

// listMessagesProvider is the default provider: it runs the message list
// command with a JSON writer and decodes what it prints.
//
// Calling the command rather than reading the registry here is deliberate,
// for the reason statusCommandProvider spells out — List already owns the
// merge with the workspace's own publishes declarations, the schema pin, the
// producing channels, and the refusal when no registry is configured. A
// second implementation would have to get all of them right again.
func listMessagesProvider(root, version string) messageProvider {
	return func(ctx context.Context) ([]message.Entry, []string) {
		var out, logs bytes.Buffer
		err := message.List(ctx, message.ListOptions{
			Dir:          root,
			OutputFormat: message.OutputJSON,
			UserAgent:    "intropy-cli/" + version,
			Stdout:       &out,
			Stderr:       &logs,
		})
		diagnostics := diagnosticLines(logs.String())
		if err != nil {
			// The command's own message, verbatim: it already names every
			// way to configure a registry, and a paraphrase here would be a
			// second thing to keep true.
			return nil, append(diagnostics, err.Error())
		}
		var entries []message.Entry
		if err := json.Unmarshal(out.Bytes(), &entries); err != nil {
			// The command succeeded but printed something this cannot read —
			// a version skew rather than anything about the messages.
			return nil, append(diagnostics, fmt.Sprintf("read message list output: %v", err))
		}
		return entries, diagnostics
	}
}

// messageReport is the /api/messages payload. Messages is always an array
// (never null) even when empty, and Diagnostics carries the reasons a
// result is thin — an unconfigured registry above all.
type messageReport struct {
	Messages    []message.Entry `json:"messages"`
	Diagnostics []string        `json:"diagnostics,omitempty"`
}

// listMessages serves the messages the create surfaces offer: the registry's
// definitions merged with what this workspace publishes. Cached after the
// first request like the topology is — a form's per-keystroke suggestion
// refresh must not cost a registry round-trip each.
func (s *apiServer) listMessages(w http.ResponseWriter, r *http.Request) {
	entries, diagnostics := s.cachedMessages(r.Context(), false)
	writeJSON(w, http.StatusOK, messageReport{
		Messages:    append(make([]message.Entry, 0, len(entries)), entries...),
		Diagnostics: diagnostics,
	})
}

// refreshMessages drops the cache and serves the fresh listing — how a
// message published while the dashboard runs is picked up without a
// restart, the same escape hatch the topology and template endpoints offer.
func (s *apiServer) refreshMessages(w http.ResponseWriter, r *http.Request) {
	entries, diagnostics := s.cachedMessages(r.Context(), true)
	writeJSON(w, http.StatusOK, messageReport{
		Messages:    append(make([]message.Entry, 0, len(entries)), entries...),
		Diagnostics: diagnostics,
	})
}

// cachedMessages returns the provider result — computed on first use or when
// force is set, reused otherwise. Concurrent requests share one computation,
// the same bargain topoMu makes for the hosts' graph verbs.
func (s *apiServer) cachedMessages(ctx context.Context, force bool) ([]message.Entry, []string) {
	s.msgMu.Lock()
	defer s.msgMu.Unlock()
	if !s.msgLoaded || force {
		s.msgEntries, s.msgDiags = s.messages(ctx)
		s.msgLoaded = true
	}
	return s.msgEntries, s.msgDiags
}

// registryRefs returns the registry-served message references, for offering
// as prompt suggestions on a template's message parameters. Workspace
// messages are excluded: they reach the suggestion pool through workspace
// facts, which know which record declares each one.
func (s *apiServer) registryRefs(ctx context.Context) []string {
	entries, _ := s.cachedMessages(ctx, false)
	var refs []string
	for _, e := range entries {
		if e.Source == message.SourceRegistry {
			refs = append(refs, e.Message)
		}
	}
	return refs
}

