// so — nothing is guessed here.
//
// No channel picker is passed. An ambiguous message comes back as the
// resolution's own error listing every candidate channel, which is the
// honest answer to a request: a browser has no prompt, and picking one on
// the user's behalf would wire the component to someone else's channel.
func (s *apiServer) wireMessage(ctx context.Context, opts *template.CreateOptions, name, tag string) error {
	lib, err := s.fetchLibrary(ctx)
	if err != nil {
		return err
	}
	defer lib.Close()
	desc, err := lib.Describe(name)
	if err != nil {
		return err
	}

	ref := opts.SetValues[template.KeyMessage]
	_ = ref // the reference travels on the request, not in values
	switch template.MessageDirection(desc.Labels[template.TemplateBlockKindLabel]) {
	case template.MessageDirectionSubscribe:
		block, err := message.Subscribe(ctx, message.SubscribeOptions{
			Ref:       s.pendingMessage,
			UserAgent: s.templates.userAgent,
		})
		if err != nil {
			return err
		}
		opts.Subscribe = block
	case template.MessageDirectionPublish:
		block, err := message.Publishes(ctx, message.PublishesOptions{
			Ref:       s.pendingMessage,
			UserAgent: s.templates.userAgent,
		})
		if err != nil {
			return err
		}
		opts.Publishes = block
	default:
		// Direction-neutral: hand the reference to Create, whose gate
		// reports a template that carries no message parameters and one
		// whose kind wires no messages, each with its own remediation.
		opts.Subscribe = &template.SubscribeBlock{Message: s.pendingMessage}
	}
	return nil
}

// messageWiringStatus maps a wiring refusal to the status a form can act
// on. An unconfigured registry is the operator's configuration (503); a
// message the registry cannot resolve, or resolves ambiguously, is the
// request's own reference (422). Everything else is upstream.
func messageWiringStatus(err error) int {
	switch {
	case errors.Is(err, config.ErrNoRegistryURL):
		return http.StatusServiceUnavailable
	case errors.As(err, new(*xregistry.MessageNotFoundError)),
		errors.As(err, new(*xregistry.AmbiguousProducerError)),
		errors.As(err, new(*xregistry.NoProducerError)):
		return http.StatusUnprocessableEntity
	}
	return http.StatusBadGateway
}

