	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/message"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/template/templatetest"
)

// fakeMessages is a provider serving a fixed listing, and counting the calls
// so the cache can be asserted.
func fakeMessages(entries []message.Entry, diagnostics []string, calls *int) messageProvider {
	return func(context.Context) ([]message.Entry, []string) {
		if calls != nil {
			*calls++
		}
		return entries, diagnostics
	}
}

var testMessages = []message.Entry{
	{
		Message:  "io.intropy.acme.product.export",
		Source:   message.SourceRegistry,
		Group:    "io.intropy.acme.product",
		Channels: []string{"product-distribution-pubsub/sbt-product-export-001"},
	},
	{
		Message: "io.intropy.acme.order.created",
		Source:  message.SourceWorkspace,
		Path:    "sales/order-extractor",
	},
}

// The endpoint serves what the command printed, unchanged.
func TestListMessagesServesTheCommandOutput(t *testing.T) {
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		messages: fakeMessages(testMessages, nil, nil),
	})

	rec := get(t, h, "/api/messages")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	var report messageReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(report.Messages) != 2 {
		t.Fatalf("messages = %d, want 2", len(report.Messages))
	}
	if report.Messages[0].Message != "io.intropy.acme.product.export" {
		t.Errorf("first message = %+v, want the registry's product export", report.Messages[0])
	}
	if report.Messages[0].Channels[0] != "product-distribution-pubsub/sbt-product-export-001" {
		t.Errorf("channels = %v, want the producing channel", report.Messages[0].Channels)
	}
}

// An empty listing is an array, never null.
func TestListMessagesEmptyIsArray(t *testing.T) {
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		messages: fakeMessages(nil, nil, nil),
	})
	rec := get(t, h, "/api/messages")
	if !strings.Contains(rec.Body.String(), `"messages": []`) {
		t.Errorf("body = %s, want an empty array", rec.Body.String())
	}
}

// "We could not ask" is a diagnostic, not an empty answer: an unconfigured
// registry must not render the same as a registry with no messages.
func TestListMessagesServesDiagnostics(t *testing.T) {
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		messages: fakeMessages(nil, []string{"no xRegistry configured; pass --registry-url"}, nil),
	})
	rec := get(t, h, "/api/messages")
	var report messageReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatal(err)
	}
	if len(report.Diagnostics) != 1 || !strings.Contains(report.Diagnostics[0], "no xRegistry configured") {
		t.Errorf("diagnostics = %v, want the command's own message", report.Diagnostics)
	}
}

// The listing is cached for the process — a form's per-keystroke suggestion
// refresh must not cost a registry round-trip each — and POST re-reads.
func TestMessagesCachedUntilRefresh(t *testing.T) {
	calls := 0
	h := testHandlerWith(t, t.TempDir(), providers{
		topology: emptyTopo,
		deploy:   emptyDeploy,
		messages: fakeMessages(testMessages, nil, &calls),
	})

	get(t, h, "/api/messages")
	get(t, h, "/api/messages")
	if calls != 1 {
		t.Fatalf("provider called %d times, want 1", calls)
	}
	post(t, h, "/api/messages/refresh")
	if calls != 2 {
		t.Errorf("provider called %d times after refresh, want 2", calls)
	}
}

// The message-capable manifest: a loader whose message parameter the label
// names, so the suggestion pool and the create wiring both engage.
const messageLoaderYAML = `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: test-template
  title: Test loader
  labels:
    intropy.dev/block-kind: loader
    intropy.dev/data-flow: out
    intropy.dev/message-params: message
spec:
  parameters:
    type: object
    required: [integrationName, message]
    properties:
      integrationName:
        type: string
      message:
        type: string
`

func messageLoaderLibrary(t *testing.T) *templatetest.Library {
	t.Helper()
	return templatetest.NewLibrary(t, "v1", map[string]string{
		"test-template/template.yaml":           messageLoaderYAML,
		"test-template/skeleton/README.md.tmpl": "{{ .integrationName }} subscribes {{ .message }}\n",
	})
}

// A message-capable template's message parameter is offered the registry's
// references, so the form can present them instead of asking for free text.
func TestTemplateSuggestionsOfferRegistryMessages(t *testing.T) {
	lib := messageLoaderLibrary(t)
	p := templateProviders(lib.Source(t))
	p.messages = fakeMessages(testMessages, nil, nil)
	root := t.TempDir()
	h := testHandlerWith(t, root, p)

	rec := get(t, h, "/api/templates/test-template?dir=.")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200: %s", rec.Code, rec.Body.String())
	}
	var detail struct {
		Fields []struct {
			Name        string   `json:"name"`
			Suggestions []string `json:"suggestions"`
		} `json:"fields"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &detail); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	for _, f := range detail.Fields {
		if f.Name != "message" {
			continue
		}
		for _, s := range f.Suggestions {
			if s == "io.intropy.acme.product.export" {
				return
			}
		}
		t.Fatalf("message suggestions = %v, want the registry's product export", f.Suggestions)
	}
	t.Fatal("no message field in the response")
}

// A hand-built block is refused: it would write a record whose channel and
// schema pin nothing validated, past the template's own direction gate.
func TestCreateRefusesHandSuppliedMessageBlock(t *testing.T) {
	lib := messageLoaderLibrary(t)
	h := testHandlerWith(t, t.TempDir(), templateProviders(lib.Source(t)))

	rec := postJSON(t, h, "/api/templates/test-template/create",
		`{"name":"orders","values":{"integrationName":"orders","subscribe":{"message":"io.intropy.acme.product.export"}}}`)
	if rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d, want 422: %s", rec.Code, rec.Body.String())
	}
	if !strings.Contains(rec.Body.String(), `name the message in \"message\"`) &&
		!strings.Contains(rec.Body.String(), "name the message in") {
		t.Errorf("body = %s, should point at the message field", rec.Body.String())
	}
}

// An unconfigured registry is the operator's configuration, not the
// request's: 503, with the command's own remediation served verbatim.
func TestCreateWithMessageUnconfiguredRegistry(t *testing.T) {
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv("INTROPY_REGISTRY_URL", "")
	lib := messageLoaderLibrary(t)
	h := testHandlerWith(t, t.TempDir(), templateProviders(lib.Source(t)))

	rec := postJSON(t, h, "/api/templates/test-template/create",
		`{"name":"orders","values":{"integrationName":"orders"},"message":"io.intropy.acme.product.export"}`)
	if rec.Code != http.StatusServiceUnavailable {
		t.Fatalf("status = %d, want 503: %s", rec.Code, rec.Body.String())
	}
	if !strings.Contains(rec.Body.String(), "no xRegistry configured") {
		t.Errorf("body = %s, want the command's own message", rec.Body.String())
	}
}

// The happy path: the reference resolves through the CLI and the scaffold
// record carries the whole subscribe block, counterparty included, so the
// flow canvas can render it without another registry read.
func TestCreateWithMessageWritesTheSubscribeBlock(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryFixtureURL(t))
	lib := messageLoaderLibrary(t)
	root := t.TempDir()
	h := testHandlerWith(t, root, templateProviders(lib.Source(t)))

	rec := postJSON(t, h, "/api/templates/test-template/create",
		`{"name":"ProductLoader","values":{"integrationName":"orders"},"message":"io.intropy.acme.product.export"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201: %s", rec.Code, rec.Body.String())
	}

	record, err := template.LoadScaffold(filepath.Join(root, "product-loader", template.ScaffoldRelPath))
	if err != nil {
		t.Fatalf("scaffold record: %v", err)
	}
	block, err := template.ReadSubscribeBlock(template.ScaffoldEntry{Scaffold: *record})
	if err != nil {
		t.Fatalf("record is not block-shaped: %v (values %v)", err, record.Values)
	}
	if block.Message != "io.intropy.acme.product.export" {
		t.Errorf("message = %q, want the resolved reference", block.Message)
	}
	if block.Pubsub != "product-distribution-pubsub" || block.Topic != "sbt-product-export-001" {
		t.Errorf("channel = %s/%s, want the producer endpoint's", block.Pubsub, block.Topic)
	}
	if block.Producer != "perfion-extractor" || block.Group != "io.intropy.acme.product" {
		t.Errorf("counterparty = %s/%s, want the producing endpoint and its group", block.Producer, block.Group)
	}
	if !strings.HasSuffix(block.DataschemaURL, "/product-export.v1/versions/1") {
		t.Errorf("dataschemaurl = %q, want the default version pinned", block.DataschemaURL)
	}
}

// A message the registry cannot resolve is the request's own reference, not
// a server fault: 422.
func TestCreateWithUnknownMessageIsUnprocessable(t *testing.T) {
	t.Setenv("INTROPY_REGISTRY_URL", registryFixtureURL(t))
	lib := messageLoaderLibrary(t)
	h := testHandlerWith(t, t.TempDir(), templateProviders(lib.Source(t)))

	rec := postJSON(t, h, "/api/templates/test-template/create",
		`{"name":"orders","values":{"integrationName":"orders"},"message":"io.intropy.acme.nope"}`)
	if rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("status = %d, want 422: %s", rec.Code, rec.Body.String())
	}
}

