// assembly or --subscribe is the surface that reports the broken endpoint.
func groupEndpoints(doc *xregistry.Export, groupID string) (producers, subscribers []Endpoint) {
	want := "/messagegroups/" + groupID
	for _, e := range doc.Endpoints {
